QString edit_state_signature(const EditState& state) {
  return QStringLiteral("sha1:%1").arg(QString::fromLatin1(
      QCryptographicHash::hash(
          adjustment_patch_identity_json(
              state)
              .toUtf8(),
          QCryptographicHash::Sha1)
          .toHex()));
}

QString mask_sampling_state_signature(EditState state) {
  // Local edits have their own work revision. Avoid serializing large raster
  // payloads merely to identify a changed global color/RAW input for an outline.
  // Clear the entire local groups, including disabled-but-nonneutral legacy
  // mirrors. Clearing only their enabled flags still synthesizes fresh mask
  // IDs when exposure, feather or geometry differs from the legacy defaults.
  state = merge_edit_recipe_state_by_groups(state, EditState{},
      {QStringLiteral("masks"), QStringLiteral("layers")});
  state.active_mask_index = -1;
  return edit_state_signature(state);
}

AsyncMaskJob make_async_mask_job(
    const QString& job_kind,
    const QString& stage,
    const QString& asset_id,
    const QString& file_path,
    const EditState& state,
    int generation,
    int state_revision) {
  return AsyncMaskJob{
      .job_id = QStringLiteral("%1-%2-%3")
                    .arg(job_kind, QString::number(generation),
                         QUuid::createUuid().toString(QUuid::WithoutBraces)),
      .job_kind = job_kind,
      .stage = stage,
      .asset_id = asset_id,
      .file_path = file_path,
      .state_signature = edit_state_signature(state),
      .generation = generation,
      .state_revision = state_revision,
  };
}

class ScopedBoolValue final {
 public:
  ScopedBoolValue(bool& target, bool value)
      : target_(target),
        previous_(target) {
    target_ = value;
  }
  ScopedBoolValue(const ScopedBoolValue&) = delete;
  ScopedBoolValue& operator=(const ScopedBoolValue&) = delete;
  ~ScopedBoolValue() { target_ = previous_; }

 private:
  bool& target_;
  bool previous_;
};

AsyncMaskJob make_layer_composite_render_job(
    const QString& asset_id,
    const QString& file_path,
    const QString& state_signature,
    int generation,
    int state_revision) {
  const auto signature_token =
      state_signature.mid(state_signature.indexOf(QLatin1Char(':')) + 1, 12);
  return AsyncMaskJob{
      .job_id = QStringLiteral("layer_composite-%1-%2").arg(generation).arg(signature_token),
      .job_kind = QStringLiteral("layer_composite"),
      .stage = QStringLiteral("render_request"),
      .asset_id = asset_id,
      .file_path = file_path,
      .state_signature = state_signature,
      .generation = generation,
      .state_revision = state_revision,
  };
}

AsyncMaskJob make_full_resolution_preview_render_job(
    const QString& asset_id,
    const QString& file_path,
    const QString& state_signature,
    int generation,
    int state_revision) {
  const auto signature_token =
      state_signature.mid(state_signature.indexOf(QLatin1Char(':')) + 1, 12);
  return AsyncMaskJob{
      .job_id =
          QStringLiteral("full_resolution_preview-%1-%2").arg(generation).arg(signature_token),
      .job_kind = QStringLiteral("full_resolution_preview"),
      .stage = QStringLiteral("render_request"),
      .asset_id = asset_id,
      .file_path = file_path,
      .state_signature = state_signature,
      .generation = generation,
      .state_revision = state_revision,
  };
}

void insert_async_mask_job_fields(QVariantMap* fields, const AsyncMaskJob& job) {
  if (fields == nullptr || job.job_id.isEmpty()) {
    return;
  }
  fields->insert(QStringLiteral("async_job_id"), job.job_id);
  fields->insert(QStringLiteral("async_job_kind"), job.job_kind);
  fields->insert(QStringLiteral("async_job_stage"), job.stage);
  fields->insert(QStringLiteral("async_job_asset_id"), job.asset_id);
  fields->insert(QStringLiteral("async_job_file_path"), job.file_path);
  fields->insert(QStringLiteral("async_job_state_signature"), job.state_signature);
}

