QThreadPool& brush_live_preview_worker_pool() {
  static QThreadPool pool;
  static const auto configured = []() {
    pool.setMaxThreadCount(2);
    pool.setThreadPriority(QThread::LowPriority);
    pool.setExpiryTimeout(1000);
    return true;
  }();
  (void)configured;
  return pool;
}
