QVariantMap fill_layer_definition(const QString& requested_color, const QString& name, int next_index) {
  auto color = QColor(requested_color.simplified().isEmpty() ? QStringLiteral("#808080")
                                                             : requested_color.simplified());
  if (!color.isValid()) {
    color = QColor(QStringLiteral("#808080"));
  }
  QVariantMap layer;
  layer.insert(
      QStringLiteral("id"),
      QStringLiteral("fill-%1-%2")
          .arg(QDateTime::currentMSecsSinceEpoch())
          .arg(next_index));
  layer.insert(
      QStringLiteral("name"),
      name.simplified().isEmpty() ? QStringLiteral("Fill Layer %1").arg(next_index)
                                  : name.simplified());
  layer.insert(QStringLiteral("kind"), QStringLiteral("fill"));
  layer.insert(QStringLiteral("enabled"), true);
  layer.insert(QStringLiteral("opacity"), 1.0);
  layer.insert(QStringLiteral("blendMode"), QStringLiteral("normal"));
  layer.insert(QStringLiteral("fillColor"), color.name(QColor::HexRgb));
  layer.insert(QStringLiteral("fillAlpha"), color.alphaF());
  return layer;
}

QImage shape_texture_image(const QString& data) {
  if (data.size() > 8 * 1024 * 1024) return {};
  auto bytes = QByteArray::fromBase64(data.toLatin1());
  QBuffer buffer(&bytes);
  if (!buffer.open(QIODevice::ReadOnly)) return {};
  QImageReader reader(&buffer, "PNG");
  const auto size = reader.size();
  if (size.width() < 1 || size.height() < 1 || size.width() > 1024 || size.height() > 1024) return {};
  return reader.read();
}

QBrush photo_shape_fill_brush(const QVariantMap& shape, const QRectF& bounds, const QColor& color) {
  const auto mode = shape.value(QStringLiteral("fillMode"), QStringLiteral("solid")).toString();
  if (mode == QStringLiteral("linear") || mode == QStringLiteral("radial")) {
    const auto first = QColor(shape.value(QStringLiteral("gradientStartColor"), color.name(QColor::HexArgb)).toString());
    const auto last = QColor(shape.value(QStringLiteral("gradientEndColor"), QStringLiteral("#ffffff")).toString());
    if (!first.isValid() || !last.isValid()) return Qt::NoBrush;
    if (mode == QStringLiteral("radial")) {
      const QPointF center(bounds.left() + bounds.width() * shape.value(QStringLiteral("gradientCenterX"), 0.5).toDouble(),
          bounds.top() + bounds.height() * shape.value(QStringLiteral("gradientCenterY"), 0.5).toDouble());
      QRadialGradient gradient(center, std::max(bounds.width(), bounds.height()) * 0.5 *
          shape.value(QStringLiteral("gradientRadius"), 1.0).toDouble());
      gradient.setColorAt(0, first);
      gradient.setColorAt(1, last);
      return QBrush(gradient);
    }
    const auto angle = shape.value(QStringLiteral("gradientAngle"), 0.0).toDouble() * 3.14159265358979323846 / 180.0;
    const QPointF axis(std::cos(angle), std::sin(angle));
    const auto extent = (std::abs(axis.x()) * bounds.width() + std::abs(axis.y()) * bounds.height()) * 0.5;
    QLinearGradient gradient(bounds.center() - axis * extent, bounds.center() + axis * extent);
    gradient.setColorAt(0, first);
    gradient.setColorAt(1, last);
    return QBrush(gradient);
  }
  if (mode != QStringLiteral("texture")) return QBrush(color);
  const auto texture_type = shape.value(QStringLiteral("textureType"), QStringLiteral("paper")).toString();
  const auto strength = shape.value(QStringLiteral("textureStrength"), 0.45).toDouble();
  if (strength <= 0.0) return QBrush(color);
  QImage tile;
  if (texture_type == QStringLiteral("image")) {
    const auto source = shape_texture_image(shape.value(QStringLiteral("textureData")).toString());
    if (source.isNull()) return Qt::NoBrush;
    tile = QImage(source.size(), QImage::Format_ARGB32_Premultiplied);
    tile.fill(color);
    QPainter painter(&tile);
    painter.setOpacity(strength);
    painter.drawImage(0, 0, source);
  } else {
    // Hatch tiles must contain whole periods so their edges join seamlessly.
    const int tile_size = texture_type == QStringLiteral("hatch") ? 120 : 128;
    tile = QImage(tile_size, tile_size, QImage::Format_ARGB32);
    const auto seed = shape.value(QStringLiteral("textureSeed"), 1).toUInt();
    for (int y = 0; y < tile.height(); ++y) {
      auto* row = reinterpret_cast<QRgb*>(tile.scanLine(y));
      for (int x = 0; x < tile.width(); ++x) {
        auto hash = static_cast<quint32>(x) * 374761393U + static_cast<quint32>(y) * 668265263U + seed * 2246822519U;
        hash = (hash ^ (hash >> 13U)) * 1274126177U;
        hash ^= hash >> 16U;
        const auto noise = static_cast<double>(hash & 65535U) / 65535.0;
        const auto pattern = texture_type == QStringLiteral("hatch") ? ((x + y) % 12 < 3 ? 0.25 : 1.0)
            : texture_type == QStringLiteral("grain") ? noise
            : 0.75 + 0.25 * noise - 0.12 * std::cos(static_cast<double>(y) * 3.14159265358979323846 / 4.0);
        const auto shade = 1.0 - strength * (1.0 - std::clamp(pattern, 0.0, 1.0));
        row[x] = qRgba(qRound(color.red() * shade), qRound(color.green() * shade),
            qRound(color.blue() * shade), color.alpha());
      }
    }
  }
  QBrush brush(tile);
  QTransform transform;
  transform.translate(bounds.left(), bounds.top());
  transform.rotate(shape.value(QStringLiteral("textureAngle"), 0.0).toDouble());
  const auto scale = shape.value(QStringLiteral("textureScale"), 1.0).toDouble();
  transform.scale(scale, scale);
  brush.setTransform(transform);
  return brush;
}

QImage rasterize_photo_shape(const QVariantMap& shape, const QSize& size) {
  const auto type = shape.value(QStringLiteral("type")).toString().trimmed().toLower();
  if ((type != QStringLiteral("rectangle") && type != QStringLiteral("rounded-rectangle") &&
       type != QStringLiteral("ellipse") && type != QStringLiteral("line") &&
       type != QStringLiteral("arrow")) || size.width() < 1 || size.height() < 1 ||
      size.width() > 8192 || size.height() > 8192 ||
      static_cast<qint64>(size.width()) * size.height() > 32LL * 1024 * 1024) {
    return {};
  }

  const auto start_x = shape.value(QStringLiteral("startX")).toDouble();
  const auto start_y = shape.value(QStringLiteral("startY")).toDouble();
  const auto end_x = shape.value(QStringLiteral("endX")).toDouble();
  const auto end_y = shape.value(QStringLiteral("endY")).toDouble();
  const auto stroke_width = shape.value(QStringLiteral("strokeWidth")).toDouble();
  if (!std::isfinite(start_x) || !std::isfinite(start_y) || !std::isfinite(end_x) ||
      !std::isfinite(end_y) || !std::isfinite(stroke_width) || stroke_width < 0.0 ||
      stroke_width > 512.0) {
    return {};
  }

  auto fill_color = QColor(shape.value(QStringLiteral("fillColor")).toString());
  auto stroke_color = QColor(shape.value(QStringLiteral("strokeColor")).toString());
  const auto fill_mode = shape.value(QStringLiteral("fillMode"), QStringLiteral("solid")).toString();
  const auto has_fill = type != QStringLiteral("line") && type != QStringLiteral("arrow") &&
      fill_mode != QStringLiteral("none") && fill_color.isValid() &&
      (fill_mode != QStringLiteral("solid") || fill_color.alpha() > 0);
  const auto has_stroke = stroke_color.isValid() && stroke_color.alpha() > 0 && stroke_width > 0.0;
  if (!has_fill && !has_stroke) return {};

  QImage image(size, QImage::Format_ARGB32_Premultiplied);
  if (image.isNull()) return {};
  image.fill(Qt::transparent);
  image.setColorSpace(QColorSpace(QColorSpace::SRgb));
  QPainter painter(&image);
  if (!painter.isActive()) return {};
  painter.setRenderHint(QPainter::Antialiasing, true);
  painter.setRenderHint(QPainter::SmoothPixmapTransform, true);

  const auto first = QPointF(start_x, start_y);
  const auto last = QPointF(end_x, end_y);
  QPainterPath path;
  if (type == QStringLiteral("line") || type == QStringLiteral("arrow")) {
    path.moveTo(first);
    path.lineTo(last);
  } else {
    const QRectF rect(first, last);
    const auto normalized_rect = rect.normalized();
    if (normalized_rect.width() < 1.0 || normalized_rect.height() < 1.0) return {};
    if (type == QStringLiteral("ellipse")) {
      path.addEllipse(normalized_rect);
    } else if (type == QStringLiteral("rounded-rectangle")) {
      const auto radius = qBound(0.0, shape.value(QStringLiteral("cornerRadius"), 16.0).toDouble(),
          std::min(normalized_rect.width(), normalized_rect.height()) * 0.5);
      path.addRoundedRect(normalized_rect, radius, radius);
    } else {
      path.addRect(normalized_rect);
    }
  }

  QPen pen;
  if (has_stroke) {
    pen = QPen(stroke_color, stroke_width, Qt::SolidLine, Qt::RoundCap, Qt::RoundJoin);
  } else {
    pen = QPen(Qt::NoPen);
  }
  painter.setPen(pen);
  painter.setBrush(has_fill ? photo_shape_fill_brush(shape, path.boundingRect(), fill_color) : QBrush(Qt::NoBrush));
  painter.drawPath(path);

  if (type == QStringLiteral("arrow") && stroke_color.isValid() && stroke_color.alpha() > 0) {
    const auto dx = end_x - start_x;
    const auto dy = end_y - start_y;
    const auto length = std::hypot(dx, dy);
    if (length > 1.0) {
      const auto ux = dx / length;
      const auto uy = dy / length;
      const auto head_length = std::min(length * 0.42, std::max(8.0, stroke_width * 4.0));
      const auto half_width = std::min(head_length * 0.45, std::max(4.0, stroke_width * 2.0));
      const QPointF base(end_x - ux * head_length, end_y - uy * head_length);
      QPainterPath head;
      head.moveTo(last);
      head.lineTo(base.x() - uy * half_width, base.y() + ux * half_width);
      head.lineTo(base.x() + uy * half_width, base.y() - ux * half_width);
      head.closeSubpath();
      painter.setPen(Qt::NoPen);
      painter.setBrush(stroke_color);
      painter.drawPath(head);
    }
  }
  painter.end();
  return image;
}

QByteArray encode_photo_shape_png(const QVariantMap& shape, const QSize& size) {
  const auto image = rasterize_photo_shape(shape, size);
  if (image.isNull()) return {};
  QByteArray encoded;
  QBuffer buffer(&encoded);
  if (!buffer.open(QIODevice::WriteOnly) || !image.save(&buffer, "PNG")) return {};
  return encoded;
}

QVariantMap text_layer_definition(const QString& requested_text, const QString& name, int next_index) {
  const auto text = requested_text.trimmed().isEmpty() ? QStringLiteral("Text") : requested_text;
  QVariantMap layer;
  layer.insert(
      QStringLiteral("id"),
      QStringLiteral("text-%1-%2")
          .arg(QDateTime::currentMSecsSinceEpoch())
          .arg(next_index));
  layer.insert(
      QStringLiteral("name"),
      name.simplified().isEmpty() ? QStringLiteral("Text Layer %1").arg(next_index)
                                  : name.simplified());
  layer.insert(QStringLiteral("kind"), QStringLiteral("text"));
  layer.insert(QStringLiteral("enabled"), true);
  layer.insert(QStringLiteral("opacity"), 1.0);
  layer.insert(QStringLiteral("blendMode"), QStringLiteral("normal"));
  layer.insert(QStringLiteral("text"), text);
  layer.insert(QStringLiteral("textColor"), QStringLiteral("#ffffff"));
  layer.insert(QStringLiteral("fontFamily"), QStringLiteral("Helvetica"));
  layer.insert(QStringLiteral("fontSize"), 48);
  layer.insert(QStringLiteral("fontWeight"), QStringLiteral("regular"));
  layer.insert(QStringLiteral("textAlignment"), QStringLiteral("left"));
  layer.insert(QStringLiteral("pixelWidth"), 512);
  layer.insert(QStringLiteral("pixelHeight"), 128);
  layer.insert(QStringLiteral("x"), 64);
  layer.insert(QStringLiteral("y"), 64);
  return layer;
}

QVariantMap source_layer_definition(const QString& file_path, const QString& name, int next_index) {
  const QFileInfo source_info(file_path);
  QImageReader reader(source_info.absoluteFilePath());
  auto image_size = source_image_size(source_info.absoluteFilePath());
  if (!raw_image_supported(source_info.absoluteFilePath()) &&
      (reader.transformation() & QImageIOHandler::TransformationRotate90)) image_size.transpose();
  QVariantMap layer;
  layer.insert(
      QStringLiteral("id"),
      QStringLiteral("source-%1-%2")
          .arg(QDateTime::currentMSecsSinceEpoch())
          .arg(next_index));
  layer.insert(
      QStringLiteral("name"),
      name.simplified().isEmpty() ? source_info.completeBaseName() : name.simplified());
  layer.insert(QStringLiteral("kind"), QStringLiteral("source"));
  layer.insert(QStringLiteral("enabled"), true);
  layer.insert(QStringLiteral("opacity"), 1.0);
  layer.insert(QStringLiteral("blendMode"), QStringLiteral("normal"));
  layer.insert(QStringLiteral("sourcePath"), source_info.absoluteFilePath());
  layer.insert(QStringLiteral("pixelWidth"), image_size.isValid() ? image_size.width() : 0);
  layer.insert(QStringLiteral("pixelHeight"), image_size.isValid() ? image_size.height() : 0);
  layer.insert(QStringLiteral("x"), 0);
  layer.insert(QStringLiteral("y"), 0);
  return layer;
}

QVariantMap layer_group_definition(const QString& name, int next_index) {
  const auto group_id = QStringLiteral("group-%1-%2")
                            .arg(QDateTime::currentMSecsSinceEpoch())
                            .arg(next_index);
  QVariantMap layer;
  layer.insert(QStringLiteral("id"), group_id);
  layer.insert(QStringLiteral("groupId"), group_id);
  layer.insert(
      QStringLiteral("name"),
      name.simplified().isEmpty() ? QStringLiteral("Group %1").arg(next_index)
                                  : name.simplified());
  layer.insert(QStringLiteral("kind"), QStringLiteral("group"));
  layer.insert(QStringLiteral("enabled"), true);
  layer.insert(QStringLiteral("opacity"), 1.0);
  layer.insert(QStringLiteral("blendMode"), QStringLiteral("normal"));
  layer.insert(QStringLiteral("expanded"), true);
  return layer;
}

QSize scaled_size_for_max_edge(const QSize& source_size, int max_edge) {
  if (!source_size.isValid() || max_edge <= 0) {
    return {};
  }
  if (std::max(source_size.width(), source_size.height()) <= max_edge) {
    return source_size;
  }
  return source_size.scaled(max_edge, max_edge, Qt::KeepAspectRatio);
}

SegmentationResult generate_localized_object_mask(
    const QImage& source_image,
    double normalized_x,
    double normalized_y);

SegmentationResult compute_single_point_object_pick_result(
    const QImage& source_image,
    double normalized_x,
    double normalized_y) {
  auto prompt_result = generate_object_mask(source_image, normalized_x, normalized_y);
  const auto localized_prompt_result =
      generate_localized_object_mask(source_image, normalized_x, normalized_y);
  if (should_prefer_prompt_object_pick_result(
          prompt_result,
          localized_prompt_result,
          normalized_x,
          normalized_y)) {
    prompt_result = localized_prompt_result;
  }
  if (!single_point_prompt_result_is_plausible(
          prompt_result, normalized_x, normalized_y)) {
    return {};
  }
  if (segmentation_result_is_localized_square_failure(
          source_image,
          prompt_result,
          normalized_x,
          normalized_y)) {
    return {};
  }
  return prompt_result;
}

QVector<SmartSelectPrompt> smart_select_prompt_constraints_for_path(
    const QVariantList& points) {
  QVector<SmartSelectPrompt> constraints;
  const auto prompt_maps = normalized_smart_select_prompt_maps(points);
  constraints.reserve(prompt_maps.size());
  for (const auto& value : prompt_maps) {
    const auto point = value.toMap();
    const auto type = point.value(QStringLiteral("type")).toString();
    if (type == QStringLiteral("box")) {
      const auto left = point.value(QStringLiteral("left")).toDouble();
      const auto top = point.value(QStringLiteral("top")).toDouble();
      const auto right = point.value(QStringLiteral("right")).toDouble();
      const auto bottom = point.value(QStringLiteral("bottom")).toDouble();
      constraints.append(SmartSelectPrompt{
          .x = (left + right) * 0.5,
          .y = (top + bottom) * 0.5,
          .negative = false,
          .box = QRectF(QPointF(left, top), QPointF(right, bottom))});
      continue;
    }
    constraints.append(SmartSelectPrompt{
        .x = point.value(QStringLiteral("x")).toDouble(),
        .y = point.value(QStringLiteral("y")).toDouble(),
        .negative = type == QStringLiteral("negative-point")});
  }
  return constraints;
}

bool smart_select_path_has_spatial_constraints(const QVariantList& points) {
  return std::any_of(points.cbegin(), points.cend(), [](const QVariant& value) {
    const auto type = normalized_smart_select_prompt_type(value.toMap());
    return type == QStringLiteral("box") || type == QStringLiteral("negative-point");
  });
}

SegmentationResult compute_smart_select_result(
    const QImage& source_image,
    const QVariantList& points,
    const SegmentationResult* previous_mask = nullptr) {
  const auto normalized_points = normalized_smart_select_path(points);
  const auto prompts = smart_select_prompts_for_path(points);
  const auto prompt_constraints = smart_select_prompt_constraints_for_path(points);
  const auto prompt_maps = normalized_smart_select_prompt_maps(points);
  auto positive_point_count = 0;
  auto has_box_prompt = false;
  for (const auto& value : prompt_maps) {
    const auto type = value.toMap().value(QStringLiteral("type")).toString();
    has_box_prompt = has_box_prompt || type == QStringLiteral("box");
    if (type != QStringLiteral("negative-point") && type != QStringLiteral("box")) {
      ++positive_point_count;
    }
  }
  const auto allow_multiple_prompt_components =
      !has_box_prompt && positive_point_count > 1;
  if (!normalized_points.isEmpty()) {
    const auto ai_status = ai_model_runtime_status();
    // Keep the explicit synthetic-segmentation test backend deterministic even
    // on developer machines that also have a local SAM model installed.
    const auto force_fake_segmentation =
        qEnvironmentVariableIsSet("PHOTO_EDITOR_TEST_FAKE_SEGMENTATION");
    if (ai_status.smart_selection_available && !force_fake_segmentation) {
      auto ai_result =
          generate_ai_smart_selection_mask(source_image, prompts, previous_mask);
      if (ai_result.success) {
        if (!smart_select_result_honors_prompts(
                ai_result,
                prompt_constraints,
                allow_multiple_prompt_components)) {
          ai_result.success = false;
          ai_result.error_message = QStringLiteral(
              "Smart Select returned a fragmented mask or missed a prompt. "
              "Refine with Brush or use Lasso.");
        }
        return ai_result;
      }
      if (ai_result.error_message.isEmpty()) {
        ai_result.error_message =
            QStringLiteral("SAM Smart Select did not return a mask.");
      }
      return ai_result;
    }
  }
  if (normalized_points.size() == 1) {
    const auto point = normalized_points.constFirst();
    return compute_single_point_object_pick_result(source_image, point.x(), point.y());
  }
  if (!normalized_points.isEmpty()) {
    auto result = generate_smart_select_mask(source_image, prompts);
    if (result.success && !smart_select_result_honors_prompts(
                              result,
                              prompt_constraints,
                              allow_multiple_prompt_components)) {
      result.success = false;
      result.error_message = QStringLiteral(
          "Smart Select returned a fragmented mask or missed a prompt. "
          "Refine with Brush or use Lasso.");
    }
    return result;
  }
  return {};
}

SegmentationResult generate_localized_object_mask(
    const QImage& source_image,
    double normalized_x,
    double normalized_y) {
  if (source_image.isNull() || source_image.width() < 2 || source_image.height() < 2) {
    return {};
  }

  const auto bounds =
      localized_object_pick_bounds(source_image.size(), normalized_x, normalized_y);
  if (!bounds.isValid()) {
    return {};
  }

  const auto localized_image = source_image.copy(bounds);
  if (localized_image.isNull()) {
    return {};
  }

  const auto center_x = qBound(
      0,
      static_cast<int>(std::lround(std::clamp(normalized_x, 0.0, 1.0) *
                                   static_cast<double>(std::max(source_image.width() - 1, 0)))),
      std::max(source_image.width() - 1, 0));
  const auto center_y = qBound(
      0,
      static_cast<int>(std::lround(std::clamp(normalized_y, 0.0, 1.0) *
                                   static_cast<double>(std::max(source_image.height() - 1, 0)))),
      std::max(source_image.height() - 1, 0));
  const auto localized_x =
      qBound(0.0,
             static_cast<double>(qBound(0, center_x - bounds.x(), bounds.width() - 1)) /
                 static_cast<double>(std::max(bounds.width() - 1, 1)),
             1.0);
  const auto localized_y =
      qBound(0.0,
             static_cast<double>(qBound(0, center_y - bounds.y(), bounds.height() - 1)) /
                 static_cast<double>(std::max(bounds.height() - 1, 1)),
             1.0);

  const auto local_result = generate_object_mask(localized_image, localized_x, localized_y);
  const auto refined_local_result = refine_localized_object_mask_by_seed_color(
      localized_image,
      local_result,
      localized_x,
      localized_y);
  return remap_localized_segmentation_result(
      refined_local_result,
      bounds,
      source_image.size());
}

enum class MaskPreviewMode {
  Overlay,
  ColorOnBw,
  ImageOnBw,
  Grayscale,
  BlackOnWhite,
  WhiteOnBlack,
  OnBlack,
  OnWhite,
  Outline,
  MarchingAnts,
  Edge,
  RefinementEdge,
  AffectedPixels,
  None,
};

MaskPreviewMode mask_preview_mode_from_string(const QString& value) {
  const auto normalized = value.trimmed().toLower();
  if (normalized == QStringLiteral("grayscale") || normalized == QStringLiteral("gray") ||
      normalized == QStringLiteral("grayscale-alpha") ||
      normalized == QStringLiteral("grayscale alpha") || normalized == QStringLiteral("alpha") ||
      normalized == QStringLiteral("alpha-mask") || normalized == QStringLiteral("alpha mask")) {
    return MaskPreviewMode::Grayscale;
  }
  if (normalized == QStringLiteral("color-on-bw") ||
      normalized == QStringLiteral("color on bw") ||
      normalized == QStringLiteral("color-on-b&w") ||
      normalized == QStringLiteral("color on b&w") ||
      normalized == QStringLiteral("color-overlay-on-bw") ||
      normalized == QStringLiteral("color overlay on bw") ||
      normalized == QStringLiteral("color-overlay-on-b&w") ||
      normalized == QStringLiteral("color overlay on b&w")) {
    return MaskPreviewMode::ColorOnBw;
  }
  if (normalized == QStringLiteral("image-on-bw") ||
      normalized == QStringLiteral("image on bw") ||
      normalized == QStringLiteral("image-on-b&w") ||
      normalized == QStringLiteral("image on b&w")) {
    return MaskPreviewMode::ImageOnBw;
  }
  if (normalized == QStringLiteral("black-on-white") || normalized == QStringLiteral("black on white")) {
    return MaskPreviewMode::BlackOnWhite;
  }
  if (normalized == QStringLiteral("holes") || normalized == QStringLiteral("pinholes") ||
      normalized == QStringLiteral("matte-holes") || normalized == QStringLiteral("matte holes")) {
    return MaskPreviewMode::BlackOnWhite;
  }
  if (normalized == QStringLiteral("white-on-black") || normalized == QStringLiteral("white on black")) {
    return MaskPreviewMode::WhiteOnBlack;
  }
  if (normalized == QStringLiteral("halos") || normalized == QStringLiteral("edge-halos") ||
      normalized == QStringLiteral("matte-halos") || normalized == QStringLiteral("matte halos")) {
    return MaskPreviewMode::WhiteOnBlack;
  }
  if (normalized == QStringLiteral("on-black") || normalized == QStringLiteral("on black") ||
      normalized == QStringLiteral("isolated-mask") ||
      normalized == QStringLiteral("isolated mask") || normalized == QStringLiteral("isolated") ||
      normalized == QStringLiteral("image-on-black") ||
      normalized == QStringLiteral("image on black")) {
    return MaskPreviewMode::OnBlack;
  }
  if (normalized == QStringLiteral("on-white") || normalized == QStringLiteral("on white") ||
      normalized == QStringLiteral("image-on-white") ||
      normalized == QStringLiteral("image on white")) {
    return MaskPreviewMode::OnWhite;
  }
  if (normalized == QStringLiteral("outline") || normalized == QStringLiteral("solid-outline") ||
      normalized == QStringLiteral("solid outline") || normalized == QStringLiteral("boundary") ||
      normalized == QStringLiteral("selection-outline") ||
      normalized == QStringLiteral("selection outline")) {
    return MaskPreviewMode::Outline;
  }
  if (normalized == QStringLiteral("marching-ants") || normalized == QStringLiteral("marching ants")) {
    return MaskPreviewMode::MarchingAnts;
  }
  if (normalized == QStringLiteral("rubylith") || normalized == QStringLiteral("ruby-lith") ||
      normalized == QStringLiteral("ruby lith") || normalized == QStringLiteral("red overlay") ||
      normalized == QStringLiteral("red-overlay")) {
    return MaskPreviewMode::Overlay;
  }
  if (normalized == QStringLiteral("edge") || normalized == QStringLiteral("edge-view") ||
      normalized == QStringLiteral("edge view")) {
    return MaskPreviewMode::Overlay;
  }
  if (normalized == QStringLiteral("refinement-edge") ||
      normalized == QStringLiteral("refinement edge") ||
      normalized == QStringLiteral("refine-edge") ||
      normalized == QStringLiteral("refine edge") ||
      normalized == QStringLiteral("matte-edge") ||
      normalized == QStringLiteral("matte edge")) {
    return MaskPreviewMode::Overlay;
  }
  if (normalized == QStringLiteral("affected") || normalized == QStringLiteral("affected-pixels") ||
      normalized == QStringLiteral("affected pixels")) {
    return MaskPreviewMode::Overlay;
  }
  if (normalized == QStringLiteral("none") || normalized == QStringLiteral("off") ||
      normalized == QStringLiteral("hidden") || normalized == QStringLiteral("hide")) {
    return MaskPreviewMode::None;
  }
  return MaskPreviewMode::Overlay;
}

QString mask_preview_mode_to_string(MaskPreviewMode mode) {
  switch (mode) {
    case MaskPreviewMode::Grayscale:
      return QStringLiteral("grayscale");
    case MaskPreviewMode::ColorOnBw:
      return QStringLiteral("color-on-bw");
    case MaskPreviewMode::ImageOnBw:
      return QStringLiteral("image-on-bw");
    case MaskPreviewMode::BlackOnWhite:
      return QStringLiteral("black-on-white");
    case MaskPreviewMode::WhiteOnBlack:
      return QStringLiteral("white-on-black");
    case MaskPreviewMode::OnBlack:
      return QStringLiteral("on-black");
    case MaskPreviewMode::OnWhite:
      return QStringLiteral("on-white");
    case MaskPreviewMode::Outline:
      return QStringLiteral("outline");
    case MaskPreviewMode::MarchingAnts:
      return QStringLiteral("marching-ants");
    case MaskPreviewMode::Edge:
      return QStringLiteral("edge");
    case MaskPreviewMode::RefinementEdge:
      return QStringLiteral("refinement-edge");
    case MaskPreviewMode::AffectedPixels:
      return QStringLiteral("affected");
    case MaskPreviewMode::None:
      return QStringLiteral("none");
    case MaskPreviewMode::Overlay:
    default:
      return QStringLiteral("overlay");
  }
}

bool mask_preview_mode_uses_raster_matte(MaskPreviewMode mode) {
  switch (mode) {
    case MaskPreviewMode::ColorOnBw:
    case MaskPreviewMode::ImageOnBw:
    case MaskPreviewMode::Grayscale:
    case MaskPreviewMode::BlackOnWhite:
    case MaskPreviewMode::WhiteOnBlack:
    case MaskPreviewMode::OnBlack:
    case MaskPreviewMode::OnWhite:
      return true;
    case MaskPreviewMode::Overlay:
    case MaskPreviewMode::Outline:
    case MaskPreviewMode::MarchingAnts:
    case MaskPreviewMode::Edge:
    case MaskPreviewMode::RefinementEdge:
    case MaskPreviewMode::AffectedPixels:
    case MaskPreviewMode::None:
    default:
      return false;
  }
}

QString mask_preview_display_mode_to_string(MaskPreviewMode mode) {
  switch (mode) {
    case MaskPreviewMode::Overlay:
      return QStringLiteral("overlay");
    case MaskPreviewMode::Outline:
      return QStringLiteral("outline");
    case MaskPreviewMode::MarchingAnts:
      return QStringLiteral("marching-ants");
    case MaskPreviewMode::Grayscale:
      return QStringLiteral("grayscale-alpha");
    case MaskPreviewMode::OnBlack:
    case MaskPreviewMode::OnWhite:
    case MaskPreviewMode::BlackOnWhite:
    case MaskPreviewMode::WhiteOnBlack:
      return QStringLiteral("isolated-mask");
    case MaskPreviewMode::None:
      return QStringLiteral("hidden");
    case MaskPreviewMode::ColorOnBw:
      return QStringLiteral("color-on-bw");
    case MaskPreviewMode::ImageOnBw:
      return QStringLiteral("image-on-bw");
    case MaskPreviewMode::Edge:
      return QStringLiteral("edge");
    case MaskPreviewMode::RefinementEdge:
      return QStringLiteral("refinement-edge");
    case MaskPreviewMode::AffectedPixels:
      return QStringLiteral("affected");
    default:
      return QStringLiteral("overlay");
  }
}

QString normalized_mask_refinement_preview_mode(const QString& value) {
  const auto normalized = value.trimmed().toLower();
  if (normalized == QStringLiteral("original") ||
      normalized == QStringLiteral("show-original") ||
      normalized == QStringLiteral("show original") ||
      normalized == QStringLiteral("before")) {
    return QStringLiteral("original");
  }
  return QStringLiteral("refined");
}

bool mask_refinement_preview_shows_original(const QString& value) {
  return normalized_mask_refinement_preview_mode(value) == QStringLiteral("original");
}

int mask_refinement_preview_source_edge(bool high_quality, bool full_resolution = false) {
  if (full_resolution) {
    return 0;
  }
  return high_quality ? 1024 : 512;
}

