  reference.soft_proof_profile = current.soft_proof_profile;
  reference.proof_icc_profile_asset = current.proof_icc_profile_asset;
  reference.proof_render_intent = current.proof_render_intent;
  reference.proof_simulate_paper_white = current.proof_simulate_paper_white;
  reference.proof_simulate_ink_black = current.proof_simulate_ink_black;
