bool EditorPreviewController::displayPreviewNativeFullResolution() const {
  const auto native_size = displayPreviewNativeSize();
  if (!native_size.isValid() || native_size.width() <= 0 || native_size.height() <= 0) {
    return false;
  }
  const auto current_state_signature = edit_state_signature(currentState());
  const auto recorded_full_output_size =
      !last_full_render_state_signature_.isEmpty() &&
              last_full_render_state_signature_ == current_state_signature
          ? last_full_render_output_size_
          : QSize{};
  const auto controller_source_size = QSize(sourceImageWidth(), sourceImageHeight());
  const auto expected_output_size =
      recorded_full_output_size.isValid()
          ? recorded_full_output_size
          : (controller_source_size.isValid()
                 ? (crop_editing_
                        ? controller_source_size
                        : crop_rect_for_image(controller_source_size, currentState()).size())
                 : QSize{});
  const auto full_resolution_size =
      expected_output_size.isValid()
          ? expected_output_size
          : (last_render_source_size_.isValid()
                 ? last_render_source_size_
                 : (controller_source_size.isValid() ? controller_source_size
                                                     : last_render_output_size_));
  return full_resolution_size.isValid() &&
         full_resolution_size.width() > 0 &&
         full_resolution_size.height() > 0 &&
         native_size.width() >= full_resolution_size.width() &&
         native_size.height() >= full_resolution_size.height();
}
bool EditorPreviewController::displayPreviewNativeViewportFullResolution() const {
  if (!displayPreviewNativeFullResolution()) {
    return false;
  }
  const auto native_size = displayPreviewNativeSize();
  if (display_preview_native_full_resolution_coverage_size_ != native_size ||
      display_preview_native_full_resolution_coverage_state_signature_ !=
          edit_state_signature(currentState()) ||
      display_preview_native_full_resolution_coverage_.isEmpty()) {
    return false;
  }

  const auto native_bounds = QRect(QPoint(0, 0), native_size);
  if (!preview_viewport_active_ || !preview_viewport_rect_.isValid()) {
    // QRegion::contains(QRect) tests overlap, not complete coverage. A single
    // uploaded tile must not qualify the rest of the image as rendered.
    return QRegion(native_bounds).subtracted(
        display_preview_native_full_resolution_coverage_).isEmpty();
  }

  const auto left = qBound(
      0,
      static_cast<int>(std::floor(
          preview_viewport_rect_.left() * static_cast<double>(native_size.width()))),
      native_size.width() - 1);
  const auto top = qBound(
      0,
      static_cast<int>(std::floor(
          preview_viewport_rect_.top() * static_cast<double>(native_size.height()))),
      native_size.height() - 1);
  const auto right = qBound(
      left + 1,
      static_cast<int>(std::ceil(
          preview_viewport_rect_.right() * static_cast<double>(native_size.width()))),
      native_size.width());
  const auto bottom = qBound(
      top + 1,
      static_cast<int>(std::ceil(
          preview_viewport_rect_.bottom() * static_cast<double>(native_size.height()))),
      native_size.height());
  return QRegion(QRect(left, top, right - left, bottom - top)).subtracted(
      display_preview_native_full_resolution_coverage_).isEmpty();
}
