bool EditorPreviewController::retryPreviewRender() {
  if (!hasAsset() || file_path_.isEmpty() || processing_) {
    return false;
  }
  renderPreview(true, QStringLiteral("preview_retry"));
  return true;
}

bool EditorPreviewController::retryThumbnailRender() {
  if (!hasAsset() || file_path_.isEmpty()) {
    return false;
  }
  thumbnail_cache_session_.maskDirty() = true;
  thumbnail_cache_session_.photoLayerDirty() = true;
  scheduleThumbnailRefreshQueue(QStringLiteral("thumbnail_retry"));
  renderPreview(false, QStringLiteral("preview_retry"));
  emit controlsChanged();
  return true;
}

bool EditorPreviewController::requestLayerFullResolutionPreview() {
  if (!hasAsset() || file_path_.isEmpty()) {
    return false;
  }
  submitLayerCompositeEditIntent(
      QStringLiteral("layer_target_selected"),
      true,
      QStringLiteral("photo_layer_change"));
  return true;
}

bool EditorPreviewController::applyExternalAdjustmentPatchEdit(
    const QString& asset_id,
    const QString& previous_adjustment_patch_json,
    const QString& adjustment_patch_json,
    const QString& history_label) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  const auto normalized_asset_id = asset_id.trimmed();
  const auto next_adjustments = parse_adjustment_patch_json(adjustment_patch_json);
  if (normalized_asset_id.isEmpty() || !next_adjustments.ok() ||
      next_adjustments.scope != AdjustmentPatchScope::AssetBound) {
    return false;
  }
  const auto& next_state = *next_adjustments.state;
  const auto active_asset = normalized_asset_id == asset_id_;
  const auto previous_adjustments = parse_adjustment_patch_json(previous_adjustment_patch_json);
  auto previous_state = previous_adjustments.ok() &&
                                previous_adjustments.scope == AdjustmentPatchScope::AssetBound
                            ? *previous_adjustments.state
                            : EditRecipeState{};
  if (active_asset) {
    previous_state = currentState();
  } else if (history_service_.hasCachedState(normalized_asset_id)) {
    previous_state = history_service_.cachedState(normalized_asset_id);
  }
  if (edit_states_equal(previous_state, next_state)) {
    if (active_asset) {
      requestLayerFullResolutionPreview();
    }
    return false;
  }

  auto& undo_stack = undoStackForAsset(normalized_asset_id);
  auto& undo_labels = undoLabelStackForAsset(normalized_asset_id);
  const auto label = history_label.trimmed().isEmpty() ? QStringLiteral("Looksy assistant edit")
                                                       : history_label.trimmed();
  const auto last_undo = undo_stack.isEmpty() ? std::optional<EditState>{} : undo_stack.back().residentState();
  if (!last_undo || !edit_states_equal(*last_undo, previous_state)) {
    undo_stack.push_back(history_service_.retainState(previous_state));
    undo_labels.push_back(label);
    if (undo_stack.size() > kMaxEditHistoryDepth) {
      undo_stack.removeFirst();
      if (!undo_labels.isEmpty()) {
        undo_labels.removeFirst();
      }
    }
  } else if (!undo_labels.isEmpty()) {
    undo_labels.last() = label;
  }
  redoStackForAsset(normalized_asset_id).clear();
  redoLabelStackForAsset(normalized_asset_id).clear();
  history_service_.refreshHistoryPins(asset_id_);
  history_service_.setCachedState(normalized_asset_id, next_state);
  if (active_asset) {
    applyState(next_state);
    persistCurrentState();
    scheduleControlsChanged();
    emit historyChanged();
    submitFullPipelineEditIntent(
        QStringLiteral("agent_edit_applied"), true, QStringLiteral("agent_edit_applied"));
    setStatus(QStringLiteral("Looksy edit applied at full resolution."));
  }
  return true;
}

