QStringList EditorPreviewController::brushPresetNames() const {
  QStringList names;
  names.reserve(
      static_cast<qsizetype>(brush_presets().size()) + custom_brush_presets_.size());
  for (const auto& preset : brush_presets()) {
    names.push_back(preset.name);
  }
  for (const auto& preset_value : custom_brush_presets_) {
    const auto name =
        normalized_brush_preset_name(preset_value.toMap().value(QStringLiteral("name")).toString());
    if (!name.isEmpty() && !names.contains(name)) {
      names.push_back(name);
    }
  }
  return names;
}
int EditorPreviewController::activeMaskBrushPointCount() const {
  auto point_count =
      static_cast<int>(activeMaskDefinition().value(QStringLiteral("brushPoints")).toList().size());
  if (brush_stroke_active_ && activeMaskKind() == QStringLiteral("brush")) {
    point_count += static_cast<int>(active_brush_live_points_.size());
  }
  return point_count;
}
QVariantList EditorPreviewController::activeMaskLiveBrushPoints() const {
  if (activeMaskKind() != QStringLiteral("brush")) {
    return {};
  }
  const auto active_mask_id =
      activeMaskDefinition().value(QStringLiteral("id")).toString();
  const auto* source_points = &active_brush_live_points_;
  if (!brush_stroke_active_) {
    if (pending_brush_commit_preview_points_.isEmpty() ||
        active_mask_id != pending_brush_commit_preview_mask_id_) {
      return {};
    }
    source_points = &pending_brush_commit_preview_points_;
  }
  QVariantList points;
  points.reserve(source_points->size());
  for (const auto& point : *source_points) {
    points.append(brush_point_variant(point));
  }
  return points;
}
