QString EditorPreviewController::smartSelectPreviewSource() const {
  if (mask_preview_temporarily_hidden_ || smart_select_preview_mask_.isEmpty()) {
    mask_session_.clearSmartSelectionPreview();
    return {};
  }
  const auto preview_mode = mask_preview_mode_from_string(maskPreviewMode());
  if (!mask_preview_mode_uses_raster_matte(preview_mode)) {
    mask_session_.clearSmartSelectionPreview();
    return {};
  }
  const auto cache_key = QString::fromLatin1(
      QCryptographicHash::hash(
          QJsonDocument::fromVariant(QVariantMap{
                                         {QStringLiteral("mask"), smart_select_preview_mask_},
                                         {QStringLiteral("previewMode"), maskPreviewMode()},
                                         {QStringLiteral("previewOverlayColor"), maskPreviewOverlayColor()},
                                     })
              .toJson(QJsonDocument::Compact),
          QCryptographicHash::Sha1)
          .toHex());
  QString cached_source;
  if (mask_session_.smartSelectionPreviewLookup(cache_key, &cached_source)) {
    return cached_source;
  }
  const auto preview_source =
      segmentation_mask_preview_source(
          smart_select_preview_mask_,
          maskPreviewMode(),
          0.40,
          maskPreviewOverlayColor());
  mask_session_.storeSmartSelectionPreview(cache_key, preview_source);
  return preview_source;
}
QVariantList EditorPreviewController::smartSelectPreviewOutlinePoints() const {
  if (smart_select_preview_mask_.isEmpty()) {
    smart_select_preview_outline_cache_valid_ = false;
    smart_select_preview_outline_cache_points_.clear();
    return {};
  }
  if (smart_select_preview_outline_cache_valid_) {
    ++smart_select_preview_outline_cache_hit_count_;
    return smart_select_preview_outline_cache_points_;
  }
  ++smart_select_preview_outline_cache_miss_count_;
  smart_select_preview_outline_cache_points_ =
      outline_points_for_mask(smart_select_preview_mask_);
  smart_select_preview_outline_cache_valid_ = true;
  return smart_select_preview_outline_cache_points_;
}
