void EditorPreviewController::schedulePreviewViewportPublication(
    double normalized_x, double normalized_y, double normalized_width,
    double normalized_height, double source_width, double source_height,
    double display_width, double display_height, double device_pixel_ratio,
    bool mask_work_active, bool pixel_inspection_active, bool active, bool immediate, bool force) {
  preview_publisher_.schedule(
      PreviewViewportPresentation{
          .normalized_x = normalized_x, .normalized_y = normalized_y,
          .normalized_width = normalized_width, .normalized_height = normalized_height,
          .visible_source_pixel_width = source_width, .visible_source_pixel_height = source_height,
          .visible_display_width = display_width, .visible_display_height = display_height,
          .device_pixel_ratio = device_pixel_ratio, .mask_work_active = mask_work_active,
          .pixel_inspection_active = pixel_inspection_active, .active = active},
      immediate,
      force);
}

void EditorPreviewController::setPreviewViewport(
    double normalized_x,
    double normalized_y,
    double normalized_width,
    double normalized_height,
    int patch_max_edge,
    bool active) {
  const auto clamped_width = qBound(0.0, normalized_width, 1.0);
  const auto clamped_height = qBound(0.0, normalized_height, 1.0);
  const auto next_rect = active && clamped_width > 0.0 && clamped_height > 0.0
                             ? QRectF(
                                   qBound(0.0, normalized_x, 1.0 - clamped_width),
                                   qBound(0.0, normalized_y, 1.0 - clamped_height),
                                   clamped_width,
                                   clamped_height)
                             : QRectF();
  const auto next_patch_edge = std::max(0, patch_max_edge);

  const auto viewport_request_unchanged =
      preview_viewport_active_ == active &&
      preview_viewport_rect_ == next_rect &&
      preview_viewport_patch_max_edge_ == next_patch_edge;
  if (viewport_request_unchanged &&
      (!active || displayPreviewNativeViewportFullResolution())) {
    return;
  }

  const auto viewport_was_full_resolution =
      displayPreviewNativeViewportFullResolution();
  const auto viewport_was_active = preview_viewport_active_;
  preview_viewport_active_ = active && next_rect.isValid();
  preview_viewport_rect_ = preview_viewport_active_ ? next_rect : QRectF();
  preview_viewport_patch_max_edge_ = preview_viewport_active_ ? next_patch_edge : 0;
  emit previewViewportChanged();
  if (viewport_was_full_resolution !=
      displayPreviewNativeViewportFullResolution()) {
    emit displayPreviewNativeViewportFullResolutionChanged();
  }
  if (!hasAsset()) {
    return;
  }

  const auto resident_viewport_ready =
      preview_viewport_active_ && !compare_mode_ &&
      displayPreviewNativeViewportFullResolution();
  if (!preview_viewport_active_ || resident_viewport_ready) {
    // Zoom and pan change presentation, not the recipe. Do not submit another
    // render when the current-generation native pixels already cover the view.
    const auto had_overlay = !display_preview_overlay_source_.isEmpty() ||
                             display_preview_overlay_rect_.isValid();
    if (interactive_request_pending_ && pending_interactive_request_.overlay_only) {
      interactive_request_pending_ = false;
    }
    if (resident_viewport_ready) {
      ++overlay_generation_;
      latest_overlay_generation_->store(overlay_generation_, std::memory_order_relaxed);
      if (full_request_pending_ && pending_full_request_.visible_tile_only &&
          pending_full_request_.render_reason == QStringLiteral("viewport_change")) {
        full_request_pending_ = false;
      }
    }
    overlay_request_pending_ = false;
    display_preview_overlay_source_.clear();
    display_preview_overlay_rect_ = QRectF();
    if (image_provider_ != nullptr) {
      image_provider_->clearImage(QString::fromLatin1(kEditedPreviewOverlayImageId));
    }
    if (!resident_viewport_ready || had_overlay) {
      emit previewChanged();
    }
    if (!preview_viewport_active_ && viewport_was_active && !compare_mode_ &&
        !displayPreviewNativeViewportFullResolution()) {
      // A zoomed edit can leave only its visible patch in the native backing.
      // Fill the image on returning to Fit, including when that patch is still
      // in flight. This is presentation work for the existing edit generation.
      auto request = currentRenderRequest(true);
      request.render_reason = QStringLiteral("viewport_restore");
      request.tool_id = QStringLiteral("compare_view");
      request.interaction_id = new_interaction_id();
      request.dirty_domain = QStringLiteral("publish_texture");
      request.dirty_stages = dirty_stages_for_domain(request.dirty_domain);
      request.dirty_region = {};
      request.full_invalidation = true;
      request.visible_tile_only = false;
      request.requested_at_msecs = QDateTime::currentMSecsSinceEpoch();
      apply_max_preview_tile_plan(&request, {});
      render_scheduler_.stopFull();
      pending_full_request_ = request;
      full_request_pending_ = true;
      if (!full_render_watcher_.isRunning()) {
        full_request_pending_ = false;
        startRenderStage(true, request);
      }
    }
    updateProcessingState();
    return;
  }

  const auto viewport_requested_at_msecs = QDateTime::currentMSecsSinceEpoch();
  const auto viewport_interaction_id = new_interaction_id();

  auto visible_max_request = currentRenderRequest(true);
  visible_max_request.render_reason = QStringLiteral("viewport_change");
  visible_max_request.tool_id = QStringLiteral("compare_view");
  visible_max_request.interaction_id = viewport_interaction_id;
  visible_max_request.dirty_domain = QStringLiteral("publish_texture");
  visible_max_request.dirty_stages = dirty_stages_for_domain(visible_max_request.dirty_domain);
  visible_max_request.dirty_region = preview_viewport_rect_;
  visible_max_request.full_invalidation = true;
  visible_max_request.visible_tile_only = true;
  visible_max_request.requested_at_msecs = viewport_requested_at_msecs;
  apply_max_preview_tile_plan(&visible_max_request, preview_viewport_rect_);
  const auto expected_output_size = output_size_for_request(visible_max_request);
  const auto visible_source_pixel_edge =
      expected_output_size.isValid()
          ? std::max(
                preview_viewport_rect_.width() *
                    static_cast<double>(expected_output_size.width()),
                preview_viewport_rect_.height() *
                    static_cast<double>(expected_output_size.height()))
          : 0.0;
  const auto source_pixel_inspection_request =
      visible_source_pixel_edge > 0.0 &&
      static_cast<double>(preview_viewport_patch_max_edge_) + 0.5 >=
          visible_source_pixel_edge;
  const auto pending_visible_viewport_request =
      full_request_pending_ &&
      pending_full_request_.render_reason == QStringLiteral("viewport_change") &&
      pending_full_request_.visible_tile_only;
  const auto can_schedule_visible_max_preview =
      !render_scheduler_.fullActive() &&
      (!full_request_pending_ || pending_visible_viewport_request) &&
      preview_viewport_patch_max_edge_ > 0 &&
      source_pixel_inspection_request &&
      !visible_max_request.compare_mode &&
      visible_max_request.tile_visible_region_active &&
      visible_max_request.planned_visible_tile_count > 0;
  if (can_schedule_visible_max_preview) {
    pending_full_request_ = visible_max_request;
    full_request_pending_ = true;
    ++viewport_max_preview_schedule_count_;
    observability::logInfo(
        photoEditorPreviewLog(),
        QStringLiteral("preview.render.viewport_max_preview_scheduled"),
        {
            {QStringLiteral("file_path"), visible_max_request.file_path},
            {QStringLiteral("generation"), visible_max_request.generation},
            {QStringLiteral("render_reason"), visible_max_request.render_reason},
            {QStringLiteral("interaction_mode"), visible_max_request.interaction_mode},
            {QStringLiteral("render_mode"), visible_max_request.render_mode},
            {QStringLiteral("render_priority"), visible_max_request.render_priority},
            {QStringLiteral("dirty_domain"), visible_max_request.dirty_domain},
            {QStringLiteral("dirty_stages"), visible_max_request.dirty_stages},
            {QStringLiteral("tile_visible_region_x"), preview_viewport_rect_.x()},
            {QStringLiteral("tile_visible_region_y"), preview_viewport_rect_.y()},
            {QStringLiteral("tile_visible_region_width"), preview_viewport_rect_.width()},
            {QStringLiteral("tile_visible_region_height"), preview_viewport_rect_.height()},
            {QStringLiteral("planned_tile_count"), visible_max_request.planned_tile_count},
	            {QStringLiteral("planned_visible_tile_count"),
	             visible_max_request.planned_visible_tile_count},
	        });
    if (!full_render_watcher_.isRunning()) {
      full_request_pending_ = false;
      startRenderStage(true, visible_max_request);
    }
  }

  if (source_pixel_inspection_request) {
    ++overlay_generation_;
    latest_overlay_generation_->store(overlay_generation_, std::memory_order_relaxed);
    overlay_request_pending_ = false;
    pending_overlay_request_ = {};
    const auto had_overlay_source =
        !display_preview_overlay_source_.isEmpty() ||
        display_preview_overlay_rect_.isValid();
    display_preview_overlay_source_.clear();
    display_preview_overlay_rect_ = QRectF();
    if (image_provider_ != nullptr) {
      image_provider_->clearImage(QString::fromLatin1(kEditedPreviewOverlayImageId));
    }
    if (had_overlay_source) {
      emit previewChanged();
    }
    updateProcessingState();
    return;
  }

  ++overlay_generation_;
  latest_overlay_generation_->store(overlay_generation_, std::memory_order_relaxed);
  auto request = currentRenderRequest(false);
  request.overlay_only = true;
  request.render_reason = QStringLiteral("viewport_change");
  request.tool_id = QStringLiteral("compare_view");
  request.interaction_id = viewport_interaction_id;
  request.render_mode = QStringLiteral("visible_overlay");
  request.render_priority = render_priority_for_mode(request.render_mode);
  request.dirty_domain = QStringLiteral("publish_texture");
  request.dirty_stages = dirty_stages_for_domain(request.dirty_domain);
  request.dirty_region = preview_viewport_rect_;
  request.full_invalidation = false;
  request.generation = overlay_generation_;
  request.latest_generation = latest_overlay_generation_;
  request.requested_at_msecs = viewport_requested_at_msecs;

  if (overlay_render_watcher_.isRunning()) {
    pending_overlay_request_ = request;
    overlay_request_pending_ = true;
    updateProcessingState();
    return;
  }

  startOverlayRenderStage(request);
}

void EditorPreviewController::setCompareMode(bool compare_mode) {
  if (rendering_upgrade_preview_active_ && !compare_mode) {
    rendering_upgrade_preview_active_ = false;
    rendering_upgrade_previous_compare_mode_ = false;
    rendering_upgrade_source_model_.clear();
    emit controlsChanged();
  }
  if (compare_mode_ == compare_mode) {
    return;
  }
  compare_mode_ = compare_mode;
  if (compare_mode_ && crop_editing_) {
    crop_editing_ = false;
    emit controlsChanged();
  }
  emit compareModeChanged();
  if (hasAsset()) {
    submitFullPipelineEditIntent(
        QStringLiteral("compare_toggle"),
        !compare_mode_,
        QStringLiteral("compare_toggle"));
  }
}

void EditorPreviewController::setCompareSourceMode(const QString& source_mode) {
  const auto normalized = source_mode.trimmed().toLower();
  const auto next_mode =
      normalized == QStringLiteral("original") ||
              normalized == QStringLiteral("snapshot") ||
              normalized == QStringLiteral("external")
          ? normalized
          : QStringLiteral("auto");
  if (compare_source_mode_ == next_mode) {
    return;
  }
  compare_source_mode_ = next_mode;
  emit compareSnapshotChanged();
  if (compare_mode_ && hasAsset()) {
    submitFullPipelineEditIntent(
        QStringLiteral("compare_source"),
        false,
        QStringLiteral("compare_source_change"));
  }
}

void EditorPreviewController::setCompareSnapshotId(const QString& snapshot_id) {
  const auto normalized_id = snapshot_id.simplified();
  auto valid_id = QString{};
  if (!normalized_id.isEmpty() && !asset_id_.isEmpty()) {
    for (const auto& snapshot : history_service_.snapshotValue(asset_id_)) {
      if (snapshot.id == normalized_id) {
        valid_id = normalized_id;
        break;
      }
    }
  }
  if (compare_snapshot_id_ == valid_id) {
    return;
  }
  compare_snapshot_id_ = valid_id;
  emit compareSnapshotChanged();
  if (compare_mode_ && hasAsset() && reference_image_path_.isEmpty()) {
    submitFullPipelineEditIntent(
        QStringLiteral("compare_snapshot"),
        false,
        QStringLiteral("compare_snapshot_change"));
  }
}

bool EditorPreviewController::setSectionComparison(const QString& scope, int layer_index) {
  if (!hasAsset() || !adjustment_preview_sections().contains(scope) || layer_index < -1)
    return false;
  QString layer_id;
  if (layer_index >= 0) {
    if (layer_index >= layer_session_.layers().size()) return false;
    const auto layer = layer_session_.layers().at(layer_index).toMap();
    if (!photo_layer_supports_adjustment_recipe(layer)) return false;
    layer_id = layer.value(QStringLiteral("id")).toString();
    if (layer_id.isEmpty()) return false;
  }
  section_comparison_hold_active_ = false;
  section_comparison_previous_scope_.clear();
  section_comparison_previous_layer_id_.clear();
  if (section_comparison_scope_ == scope && section_comparison_layer_id_ == layer_id) return true;
  section_comparison_scope_ = scope;
  section_comparison_layer_id_ = layer_id;
  emit sectionComparisonChanged();
  submitFullPipelineEditIntent(QStringLiteral("section_comparison"), false,
                               QStringLiteral("section_comparison_change"));
  return true;
}

bool EditorPreviewController::beginSectionComparisonHold(const QString& scope, int layer_index) {
  if (section_comparison_hold_active_) return false;
  const auto previous_scope = section_comparison_scope_;
  const auto previous_layer_id = section_comparison_layer_id_;
  if (!setSectionComparison(scope, layer_index)) return false;
  section_comparison_previous_scope_ = previous_scope;
  section_comparison_previous_layer_id_ = previous_layer_id;
  section_comparison_hold_active_ = true;
  return true;
}

void EditorPreviewController::endSectionComparisonHold() {
  if (!section_comparison_hold_active_) return;
  const auto scope = section_comparison_previous_scope_;
  const auto layer_id = section_comparison_previous_layer_id_;
  section_comparison_hold_active_ = false;
  if (scope.isEmpty()) { clearSectionComparison(); return; }
  int index = -1;
  if (!layer_id.isEmpty()) {
    for (int candidate = 0; candidate < layer_session_.layers().size(); ++candidate) {
      if (layer_session_.layers().at(candidate).toMap().value(QStringLiteral("id")).toString() == layer_id) {
        index = candidate;
        break;
      }
    }
    if (index < 0) { clearSectionComparison(); return; }
  }
  setSectionComparison(scope, index);
}

void EditorPreviewController::clearSectionComparison() {
  section_comparison_hold_active_ = false;
  section_comparison_previous_scope_.clear();
  section_comparison_previous_layer_id_.clear();
  if (section_comparison_scope_.isEmpty()) return;
  section_comparison_scope_.clear();
  section_comparison_layer_id_.clear();
  emit sectionComparisonChanged();
  submitFullPipelineEditIntent(QStringLiteral("section_comparison"), false,
                               QStringLiteral("section_comparison_change"));
}

