void EditorPreviewController::setCropEditing(bool crop_editing) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return;
  if (crop_editing_ == crop_editing) {
    return;
  }
  crop_editing_ = crop_editing;
  if (crop_editing_) {
    if (compare_mode_) {
      compare_mode_ = false;
      emit compareModeChanged();
    }
    if (white_balance_sampling_) {
      white_balance_sampling_ = false;
      emit whiteBalanceSamplingChanged();
    }
  }
  emit controlsChanged();
  if (hasAsset()) {
    submitEditIntent(EditIntent{
        .operation = crop_editing_ ? QStringLiteral("crop_editing_started")
                                   : QStringLiteral("crop_editing_finished"),
        .dirty_domain = QStringLiteral("geometry_transform"),
        .render_reason = QStringLiteral("crop_change"),
        .schedule_full_resolution = false,
    });
  }
}

QVariantMap EditorPreviewController::importIccProfileAsset(
    const QString& slot,
    const QString& file_path) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {{QStringLiteral("ok"), false}, {QStringLiteral("errorCode"), QStringLiteral("access_required")}, {QStringLiteral("error"), QStringLiteral("Editing requires an active trial or purchase.")}};
  const auto normalized_slot = slot.trimmed().toLower();
  if (normalized_slot == QStringLiteral("input") && !file_path_.isEmpty()) {
    photo_editor::pipeline::DecodedImageMetadata metadata;
    const auto raw_source = raw_image_supported(file_path_);
    const auto boundary_available =
        raw_source &&
        read_raw_decoded_metadata(
            file_path_,
            &metadata,
            raw_decode_settings_for_state(currentState()));
    if (raw_source &&
        (!boundary_available ||
         !photo_editor::pipeline::decoded_image_accepts_custom_input_profile(metadata))) {
      setStatus(QStringLiteral(
          "This RAW decoder has already applied its camera profile. A custom input ICC requires camera-linear RAW samples."));
      return {
          {QStringLiteral("ok"), false},
          {QStringLiteral("status"), QStringLiteral("decode_boundary_unsupported")},
          {QStringLiteral("failureReason"),
           boundary_available
               ? QStringLiteral("icc_input_profile_requires_camera_linear_raw")
               : QStringLiteral("raw_decode_color_boundary_unavailable")},
      };
    }
  }
  IccProfileAssetState* destination = nullptr;
  if (normalized_slot == QStringLiteral("input")) {
    destination = &input_icc_profile_asset_;
  } else if (normalized_slot == QStringLiteral("preview")) {
    destination = &preview_icc_profile_asset_;
  } else if (normalized_slot == QStringLiteral("proof")) {
    destination = &proof_icc_profile_asset_;
  } else if (normalized_slot == QStringLiteral("export") ||
             normalized_slot == QStringLiteral("output")) {
    destination = &export_icc_profile_asset_;
  }
  if (destination == nullptr) {
    return {
        {QStringLiteral("ok"), false},
        {QStringLiteral("status"), QStringLiteral("invalid_slot")},
        {QStringLiteral("failureReason"), QStringLiteral("icc_profile_asset_slot_invalid")},
    };
  }

  const QUrl source_url(file_path.trimmed());
  const auto local_path = source_url.isLocalFile()
                              ? source_url.toLocalFile()
                              : QFileInfo(file_path.trimmed()).absoluteFilePath();
  auto imported = photo_editor::pipeline::default_icc_profile_asset_registry().import_file(
      local_path.toStdString());
  if (!imported.ready()) {
    setStatus(QStringLiteral("Could not import ICC profile: %1")
                  .arg(QString::fromStdString(imported.failure_reason)));
    return {
        {QStringLiteral("ok"), false},
        {QStringLiteral("status"),
         QString::fromLatin1(photo_editor::pipeline::icc_profile_asset_status_name(
             imported.status))},
        {QStringLiteral("failureReason"), QString::fromStdString(imported.failure_reason)},
    };
  }

  const auto working_profile = photo_editor::pipeline::working_color_profile_from_name(
      working_color_profile_.toStdString());
  const auto transform_options = photo_editor::pipeline::IccTransformOptions{
      .rendering_intent = normalized_slot == QStringLiteral("input")
                              ? photo_editor::pipeline::IccRenderingIntent::RelativeColorimetric
                              : (render_intent_.compare(
                                     QStringLiteral("Relative Colorimetric"),
                                     Qt::CaseInsensitive) == 0
                                     ? photo_editor::pipeline::IccRenderingIntent::RelativeColorimetric
                                     : photo_editor::pipeline::IccRenderingIntent::Perceptual),
      .black_point_compensation =
          normalized_slot == QStringLiteral("input") ? true : black_point_compensation_enabled_,
      .pixel_format = photo_editor::pipeline::IccPixelFormat::RgbaFloat32,
      .target = normalized_slot == QStringLiteral("input")
                    ? "input-to-working"
                    : (normalized_slot == QStringLiteral("export") ||
                               normalized_slot == QStringLiteral("output")
                           ? "export-output"
                           : "preview-output"),
  };
  auto transform = photo_editor::pipeline::CompiledIccTransform{};
  if (normalized_slot == QStringLiteral("input")) {
    transform = photo_editor::pipeline::compile_icc_to_builtin_transform(
        imported.payload_bytes(),
        working_profile.color_space,
        transform_options);
  } else if (normalized_slot == QStringLiteral("proof")) {
    const auto source_payload =
        photo_editor::pipeline::builtin_rgb_icc_profile_payload(
            working_profile.color_space);
    const auto preview_profile =
        photo_editor::pipeline::output_color_profile_from_name(
            (preview_color_space_.trimmed().isEmpty()
                 ? output_color_space_
                 : preview_color_space_)
                .toStdString());
    const auto destination_payload =
        photo_editor::pipeline::builtin_rgb_icc_profile_payload(
            preview_profile.color_space);
    transform = photo_editor::pipeline::compile_icc_proofing_transform(
        source_payload,
        imported.payload_bytes(),
        destination_payload,
        photo_editor::pipeline::IccProofTransformOptions{
            .rendering_intent = transform_options.rendering_intent,
            .proofing_intent = proof_simulate_paper_white_
                                   ? photo_editor::pipeline::IccRenderingIntent::AbsoluteColorimetric
                                   : (proof_render_intent_.compare(
                                          QStringLiteral("Perceptual"),
                                          Qt::CaseInsensitive) == 0
                                          ? photo_editor::pipeline::IccRenderingIntent::Perceptual
                                          : photo_editor::pipeline::IccRenderingIntent::RelativeColorimetric),
            .black_point_compensation = black_point_compensation_enabled_ &&
                                        !proof_simulate_paper_white_ &&
                                        !proof_simulate_ink_black_,
            .gamut_check = false,
            .pixel_format = photo_editor::pipeline::IccPixelFormat::RgbaFloat32,
            .target = "soft-proof-import-validation",
        });
  } else {
    transform = photo_editor::pipeline::compile_builtin_to_icc_transform(
        working_profile.color_space,
        imported.payload_bytes(),
        transform_options);
  }
  if (!transform.ready()) {
    setStatus(QStringLiteral("Unsupported ICC profile: %1")
                  .arg(QString::fromStdString(transform.description().failure_reason)));
    return {
        {QStringLiteral("ok"), false},
        {QStringLiteral("status"), QStringLiteral("transform_compile_failed")},
        {QStringLiteral("failureReason"),
         QString::fromStdString(transform.description().failure_reason)},
    };
  }

  const auto imported_state = IccProfileAssetState{
      .asset_id = QString::fromStdString(imported.reference.asset_id),
      .payload_sha256 = QString::fromStdString(imported.reference.payload_sha256),
      .display_name = QString::fromStdString(imported.reference.display_name),
      .source_uri = QString::fromStdString(imported.reference.source_uri),
      .source_kind = QString::fromStdString(imported.reference.source_kind),
      .byte_size = static_cast<qint64>(imported.reference.byte_size),
  };
  if (*destination != imported_state) {
    rememberStateForUndo();
    *destination = imported_state;
    persistCurrentState();
    emit controlsChanged();
    if (normalized_slot == QStringLiteral("input")) {
      submitInputColorTransformEditIntent(QStringLiteral("custom_input_icc_profile"));
    } else {
      submitDisplayTransformEditIntent(QStringLiteral("custom_%1_icc_profile").arg(normalized_slot));
    }
  }
  setStatus(QStringLiteral("Using ICC profile '%1' for %2.")
                .arg(imported_state.display_name, normalized_slot));
  return {
      {QStringLiteral("ok"), true},
      {QStringLiteral("status"), QStringLiteral("ready")},
      {QStringLiteral("slot"), normalized_slot},
      {QStringLiteral("assetId"), imported_state.asset_id},
      {QStringLiteral("payloadSha256"), imported_state.payload_sha256},
      {QStringLiteral("byteSize"), imported_state.byte_size},
      {QStringLiteral("transformCacheKey"),
       QString::fromStdString(transform.description().cache_key)},
  };
}

QVariantMap EditorPreviewController::relinkIccProfileAsset(
    const QString& slot,
    const QString& file_path) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {{QStringLiteral("ok"), false}, {QStringLiteral("errorCode"), QStringLiteral("access_required")}, {QStringLiteral("error"), QStringLiteral("Editing requires an active trial or purchase.")}};
  const auto normalized_slot = slot.trimmed().toLower();
  if (normalized_slot == QStringLiteral("input") && !file_path_.isEmpty()) {
    photo_editor::pipeline::DecodedImageMetadata metadata;
    const auto raw_source = raw_image_supported(file_path_);
    const auto boundary_available =
        raw_source &&
        read_raw_decoded_metadata(
            file_path_,
            &metadata,
            raw_decode_settings_for_state(currentState()));
    if (raw_source &&
        (!boundary_available ||
         !photo_editor::pipeline::decoded_image_accepts_custom_input_profile(metadata))) {
      return {
          {QStringLiteral("ok"), false},
          {QStringLiteral("status"), QStringLiteral("decode_boundary_unsupported")},
          {QStringLiteral("failureReason"),
           boundary_available
               ? QStringLiteral("icc_input_profile_requires_camera_linear_raw")
               : QStringLiteral("raw_decode_color_boundary_unavailable")},
      };
    }
  }
  IccProfileAssetState* destination = nullptr;
  if (normalized_slot == QStringLiteral("input")) {
    destination = &input_icc_profile_asset_;
  } else if (normalized_slot == QStringLiteral("preview")) {
    destination = &preview_icc_profile_asset_;
  } else if (normalized_slot == QStringLiteral("proof")) {
    destination = &proof_icc_profile_asset_;
  } else if (normalized_slot == QStringLiteral("export") ||
             normalized_slot == QStringLiteral("output")) {
    destination = &export_icc_profile_asset_;
  }
  if (destination == nullptr || !destination->configured()) {
    return {
        {QStringLiteral("ok"), false},
        {QStringLiteral("status"), QStringLiteral("invalid_slot_or_unconfigured")},
        {QStringLiteral("failureReason"), QStringLiteral("icc_profile_asset_not_configured")},
    };
  }

  const auto previous = resolve_icc_profile_asset(*destination);
  const QUrl source_url(file_path.trimmed());
  const auto local_path = source_url.isLocalFile()
                              ? source_url.toLocalFile()
                              : QFileInfo(file_path.trimmed()).absoluteFilePath();
  auto& registry = photo_editor::pipeline::default_icc_profile_asset_registry();
  registry.register_path(destination->asset_id.toStdString(), local_path.toStdString());
  auto candidate = *destination;
  candidate.source_uri = local_path;
  const auto resolved = resolve_icc_profile_asset(candidate);
  if (!resolved.ready()) {
    if (previous.ready()) {
      auto previous_path = previous.reference.source_uri;
      if (previous_path.empty() ||
          !QFileInfo(QString::fromStdString(previous_path)).exists()) {
        previous_path = previous.resolved_uri;
      }
      if (!previous_path.empty()) {
        registry.register_path(previous.reference.asset_id, previous_path);
      }
      static_cast<void>(registry.register_payload(
          previous.reference,
          previous.payload_bytes(),
          previous.resolved_uri));
    }
    setStatus(QStringLiteral("ICC profile relink failed: %1")
                  .arg(QString::fromStdString(resolved.failure_reason)));
    return {
        {QStringLiteral("ok"), false},
        {QStringLiteral("status"),
         QString::fromLatin1(photo_editor::pipeline::icc_profile_asset_status_name(
             resolved.status))},
        {QStringLiteral("failureReason"), QString::fromStdString(resolved.failure_reason)},
    };
  }

  rememberStateForUndo();
  destination->source_uri = local_path;
  persistCurrentState();
  emit controlsChanged();
  if (normalized_slot == QStringLiteral("input")) {
    submitInputColorTransformEditIntent(QStringLiteral("relink_input_icc_profile"));
  } else {
    submitDisplayTransformEditIntent(QStringLiteral("relink_%1_icc_profile").arg(normalized_slot));
  }
  setStatus(QStringLiteral("Relinked ICC profile '%1'.").arg(destination->display_name));
  return {
      {QStringLiteral("ok"), true},
      {QStringLiteral("status"), QStringLiteral("ready")},
      {QStringLiteral("slot"), normalized_slot},
      {QStringLiteral("assetId"), destination->asset_id},
      {QStringLiteral("payloadSha256"), destination->payload_sha256},
      {QStringLiteral("sourceUri"), destination->source_uri},
  };
}

bool EditorPreviewController::clearIccProfileAsset(const QString& slot) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  const auto normalized_slot = slot.trimmed().toLower();
  IccProfileAssetState* destination = nullptr;
  if (normalized_slot == QStringLiteral("input")) {
    destination = &input_icc_profile_asset_;
  } else if (normalized_slot == QStringLiteral("preview")) {
    destination = &preview_icc_profile_asset_;
  } else if (normalized_slot == QStringLiteral("proof")) {
    destination = &proof_icc_profile_asset_;
  } else if (normalized_slot == QStringLiteral("export") ||
             normalized_slot == QStringLiteral("output")) {
    destination = &export_icc_profile_asset_;
  }
  if (destination == nullptr || !destination->configured()) {
    return false;
  }
  rememberStateForUndo();
  *destination = {};
  persistCurrentState();
  emit controlsChanged();
  if (normalized_slot == QStringLiteral("input")) {
    submitInputColorTransformEditIntent(QStringLiteral("clear_input_icc_profile"));
  } else {
    submitDisplayTransformEditIntent(QStringLiteral("clear_%1_icc_profile").arg(normalized_slot));
  }
  setStatus(QStringLiteral("Cleared the custom %1 ICC profile.").arg(normalized_slot));
  return true;
}

QVariantMap EditorPreviewController::importDcpProfileAsset(const QString& file_path) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {{QStringLiteral("ok"), false}, {QStringLiteral("errorCode"), QStringLiteral("access_required")}, {QStringLiteral("error"), QStringLiteral("Editing requires an active trial or purchase.")}};
  photo_editor::pipeline::DecodedImageMetadata metadata;
  const auto has_source = !file_path_.isEmpty();
  const auto raw_source = has_source && raw_image_supported(file_path_);
  const auto boundary_available =
      raw_source &&
      read_raw_decoded_metadata(
          file_path_,
          &metadata,
          raw_decode_settings_for_state(currentState()));
  if (has_source &&
      (!boundary_available ||
       !photo_editor::pipeline::decoded_image_requires_engine_input_transform(metadata))) {
    const auto reason = boundary_available
                            ? QStringLiteral("dcp_profile_requires_camera_linear_raw")
                            : QStringLiteral("raw_decode_color_boundary_unavailable");
    setStatus(QStringLiteral(
        "This DCP requires camera-linear RAW samples. The active decoder has already characterized the image."));
    return {
        {QStringLiteral("ok"), false},
        {QStringLiteral("status"), QStringLiteral("decode_boundary_unsupported")},
        {QStringLiteral("failureReason"), reason},
    };
  }

  const QUrl source_url(file_path.trimmed());
  const auto local_path = source_url.isLocalFile()
                              ? source_url.toLocalFile()
                              : QFileInfo(file_path.trimmed()).absoluteFilePath();
  const auto imported =
      photo_editor::pipeline::default_dcp_profile_asset_registry().import_file(
          local_path.toStdString());
  if (!imported.ready()) {
    setStatus(QStringLiteral("Could not import DCP profile: %1")
                  .arg(QString::fromStdString(imported.failure_reason)));
    return {
        {QStringLiteral("ok"), false},
        {QStringLiteral("status"),
         QString::fromLatin1(photo_editor::pipeline::dcp_profile_asset_status_name(
             imported.status))},
        {QStringLiteral("failureReason"), QString::fromStdString(imported.failure_reason)},
    };
  }
  if (!imported.profile->has_executable_color_transform()) {
    return {
        {QStringLiteral("ok"), false},
        {QStringLiteral("status"), QStringLiteral("execution_unsupported")},
        {QStringLiteral("failureReason"), QStringLiteral("dcp_color_transform_required")},
    };
  }
  const auto compatibility =
      boundary_available
          ? photo_editor::pipeline::dcp_profile_camera_compatibility(
                *imported.profile,
                metadata.camera_make,
                metadata.camera_model)
          : photo_editor::pipeline::DcpCameraCompatibility::Unknown;
  if (compatibility == photo_editor::pipeline::DcpCameraCompatibility::Mismatch) {
    return {
        {QStringLiteral("ok"), false},
        {QStringLiteral("status"), QStringLiteral("camera_mismatch")},
        {QStringLiteral("failureReason"), QStringLiteral("dcp_profile_camera_mismatch")},
    };
  }

  const auto imported_state = DcpProfileAssetState{
      .schema_version = static_cast<int>(imported.reference.schema_version),
      .asset_id = QString::fromStdString(imported.reference.asset_id),
      .payload_sha256 = QString::fromStdString(imported.reference.payload_sha256),
      .display_name = QString::fromStdString(imported.reference.display_name),
      .source_uri = QString::fromStdString(imported.reference.source_uri),
      .source_kind = QString::fromStdString(imported.reference.source_kind),
      .byte_size = static_cast<qint64>(imported.reference.byte_size),
  };
  rememberStateForUndo();
  camera_dcp_profile_asset_ = imported_state;
  camera_profile_rendering_model_ = QStringLiteral("dng-profile-v2");
  highlight_reconstruction_model_ = QStringLiteral("camera-linear-opposed-v2");
  input_icc_profile_asset_ = {};
  input_color_profile_ = normalized_input_color_profile_name(
      QStringLiteral("Camera DCP: %1").arg(imported_state.display_name));
  persistCurrentState();
  emit controlsChanged();
  submitInputColorTransformEditIntent(QStringLiteral("custom_camera_dcp_profile"));
  setStatus(QStringLiteral("Using DCP profile '%1'.").arg(imported_state.display_name));
  return {
      {QStringLiteral("ok"), true},
      {QStringLiteral("status"), QStringLiteral("ready")},
      {QStringLiteral("assetId"), imported_state.asset_id},
      {QStringLiteral("payloadSha256"), imported_state.payload_sha256},
      {QStringLiteral("byteSize"), imported_state.byte_size},
      {QStringLiteral("profileName"),
       QString::fromStdString(imported.profile->profile_name)},
      {QStringLiteral("uniqueCameraModel"),
       QString::fromStdString(imported.profile->unique_camera_model)},
  };
}

QVariantMap EditorPreviewController::relinkDcpProfileAsset(const QString& file_path) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {{QStringLiteral("ok"), false}, {QStringLiteral("errorCode"), QStringLiteral("access_required")}, {QStringLiteral("error"), QStringLiteral("Editing requires an active trial or purchase.")}};
  if (!camera_dcp_profile_asset_.configured()) {
    return {
        {QStringLiteral("ok"), false},
        {QStringLiteral("status"), QStringLiteral("unconfigured")},
        {QStringLiteral("failureReason"), QStringLiteral("dcp_profile_asset_not_configured")},
    };
  }
  const auto previous = resolve_dcp_profile_asset(camera_dcp_profile_asset_);
  const QUrl source_url(file_path.trimmed());
  const auto local_path = source_url.isLocalFile()
                              ? source_url.toLocalFile()
                              : QFileInfo(file_path.trimmed()).absoluteFilePath();
  auto& registry = photo_editor::pipeline::default_dcp_profile_asset_registry();
  registry.register_path(
      camera_dcp_profile_asset_.asset_id.toStdString(),
      local_path.toStdString());
  auto candidate = camera_dcp_profile_asset_;
  candidate.source_uri = local_path;
  const auto resolved = resolve_dcp_profile_asset(candidate);
  if (!resolved.ready()) {
    if (previous.ready()) {
      auto previous_path = previous.reference.source_uri;
      if (previous_path.empty() ||
          !QFileInfo(QString::fromStdString(previous_path)).exists()) {
        previous_path = previous.resolved_uri;
      }
      if (!previous_path.empty()) {
        registry.register_path(previous.reference.asset_id, previous_path);
      }
      static_cast<void>(registry.register_payload(
          previous.reference,
          previous.payload_bytes(),
          previous.resolved_uri));
    }
    setStatus(QStringLiteral("DCP profile relink failed: %1")
                  .arg(QString::fromStdString(resolved.failure_reason)));
    return {
        {QStringLiteral("ok"), false},
        {QStringLiteral("status"),
         QString::fromLatin1(photo_editor::pipeline::dcp_profile_asset_status_name(
             resolved.status))},
        {QStringLiteral("failureReason"), QString::fromStdString(resolved.failure_reason)},
    };
  }
  rememberStateForUndo();
  camera_dcp_profile_asset_.source_uri = local_path;
  persistCurrentState();
  emit controlsChanged();
  submitInputColorTransformEditIntent(QStringLiteral("relink_camera_dcp_profile"));
  setStatus(QStringLiteral("Relinked DCP profile '%1'.")
                .arg(camera_dcp_profile_asset_.display_name));
  return {
      {QStringLiteral("ok"), true},
      {QStringLiteral("status"), QStringLiteral("ready")},
      {QStringLiteral("assetId"), camera_dcp_profile_asset_.asset_id},
      {QStringLiteral("payloadSha256"), camera_dcp_profile_asset_.payload_sha256},
      {QStringLiteral("sourceUri"), camera_dcp_profile_asset_.source_uri},
  };
}

bool EditorPreviewController::clearDcpProfileAsset() {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  if (!camera_dcp_profile_asset_.configured()) {
    return false;
  }
  rememberStateForUndo();
  camera_dcp_profile_asset_ = {};
  if (photo_editor::pipeline::input_color_profile_from_name(
          input_color_profile_.toStdString()).kind ==
      photo_editor::pipeline::InputTransformKind::CameraDcpProfile) {
    input_color_profile_ = QStringLiteral("Camera Native");
  }
  persistCurrentState();
  emit controlsChanged();
  submitInputColorTransformEditIntent(QStringLiteral("clear_camera_dcp_profile"));
  setStatus(QStringLiteral("Cleared the custom DCP profile."));
  return true;
}

