void EditorPreviewController::refreshSystemMonitorProfile() {
  const auto profile = refresh_system_monitor_profile();
  const auto profile_changed =
      system_monitor_profile_identity_ != profile.identity ||
      system_monitor_display_target_identity_ !=
          profile.display_target_identity;
  const auto metadata_changed =
      system_monitor_profile_name_ != profile.display_name ||
      system_monitor_profile_discovery_ != profile.discovery_backend ||
      system_monitor_profile_display_identity_ != profile.display_identity ||
      system_monitor_profile_last_discovery_backend_ !=
          profile.last_discovery_backend ||
      system_monitor_profile_failure_reason_ != profile.failure_reason ||
      system_monitor_profile_discovery_failures_ !=
          profile.consecutive_discovery_failures ||
      system_monitor_profile_retained_after_failure_ !=
          profile.retained_after_failure ||
      system_monitor_profile_generation_ != profile.generation;
  if (!profile_changed && !metadata_changed) {
    return;
  }
  system_monitor_profile_name_ = profile.display_name;
  system_monitor_profile_identity_ = profile.identity;
  system_monitor_profile_discovery_ = profile.discovery_backend;
  system_monitor_profile_display_identity_ = profile.display_identity;
  system_monitor_display_target_identity_ =
      profile.display_target_identity;
  system_monitor_profile_last_discovery_backend_ =
      profile.last_discovery_backend;
  system_monitor_profile_failure_reason_ = profile.failure_reason;
  system_monitor_profile_discovery_failures_ =
      profile.consecutive_discovery_failures;
  system_monitor_profile_retained_after_failure_ =
      profile.retained_after_failure;
  system_monitor_profile_generation_ = profile.generation;
  emit systemMonitorProfileChanged();
  if (monitor_color_profile_.isEmpty() && hasAsset() && profile_changed) {
    submitDisplayTransformEditIntent(
        QStringLiteral("system_monitor_profile_change"));
  } else {
  }
}

void EditorPreviewController::setSoftProofEnabled(bool enabled) {
  const auto target_mode =
      enabled ? QStringLiteral("Soft Proof")
              : QStringLiteral("Monitor");
  if (soft_proof_enabled_ == enabled &&
      preview_output_mode_ == target_mode) {
    return;
  }
  rememberStateForUndo();
  soft_proof_enabled_ = enabled;
  preview_output_mode_ = target_mode;
  latest_proof_gamut_warning_mask_ =
      QImage{};
  (void)histogram_scope_session_.reconcileProofAvailability(
      soft_proof_enabled_);
  persistCurrentState();
  emit controlsChanged();
  submitDisplayTransformEditIntent(QStringLiteral("soft_proof_enabled"));
}

