bool EditorPreviewController::resetChannelMixer() {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  EditRecipeState::RgbChannelMixer identity;
  if (!rgb_channel_mixers_differ(rgb_channel_mixer_, identity)) {
    return false;
  }
  rememberStateForUndo();
  rgb_channel_mixer_ = identity;
  persistCurrentState();
  emit controlsChanged();
  submitGlobalToneColorEditIntent(QStringLiteral("channel_mixer_reset"));
  return true;
}

bool EditorPreviewController::resetChannelMixerRow(const QString& output_channel) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  const auto channel = output_channel.trimmed().toLower();
  auto next = rgb_channel_mixer_;
  if (channel == QStringLiteral("red")) {
    next.red_from_red = 100.0;
    next.red_from_green = 0.0;
    next.red_from_blue = 0.0;
  } else if (channel == QStringLiteral("green")) {
    next.green_from_red = 0.0;
    next.green_from_green = 100.0;
    next.green_from_blue = 0.0;
  } else if (channel == QStringLiteral("blue")) {
    next.blue_from_red = 0.0;
    next.blue_from_green = 0.0;
    next.blue_from_blue = 100.0;
  } else {
    return false;
  }
  if (!rgb_channel_mixers_differ(rgb_channel_mixer_, next)) {
    return false;
  }
  rememberStateForUndo();
  rgb_channel_mixer_ = next;
  persistCurrentState();
  emit controlsChanged();
  submitGlobalToneColorEditIntent(QStringLiteral("channel_mixer_reset_row"));
  return true;
}

bool EditorPreviewController::applyChannelMixerPreset(const QString& preset) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  const auto key = preset.trimmed().toLower();
  EditRecipeState::RgbChannelMixer next;
  if (key == QStringLiteral("identity")) {
    next = {};
  } else if (key == QStringLiteral("monochrome") || key == QStringLiteral("mono")) {
    next.red_from_red = 21.26;
    next.red_from_green = 71.52;
    next.red_from_blue = 7.22;
    next.green_from_red = 21.26;
    next.green_from_green = 71.52;
    next.green_from_blue = 7.22;
    next.blue_from_red = 21.26;
    next.blue_from_green = 71.52;
    next.blue_from_blue = 7.22;
  } else if (key == QStringLiteral("swap red blue") || key == QStringLiteral("swap-red-blue") ||
             key == QStringLiteral("swaprb")) {
    next.red_from_red = 0.0;
    next.red_from_green = 0.0;
    next.red_from_blue = 100.0;
    next.green_from_red = 0.0;
    next.green_from_green = 100.0;
    next.green_from_blue = 0.0;
    next.blue_from_red = 100.0;
    next.blue_from_green = 0.0;
    next.blue_from_blue = 0.0;
  } else {
    return false;
  }
  if (!rgb_channel_mixers_differ(rgb_channel_mixer_, next)) {
    return false;
  }
  rememberStateForUndo();
  rgb_channel_mixer_ = next;
  persistCurrentState();
  emit controlsChanged();
  submitGlobalToneColorEditIntent(QStringLiteral("channel_mixer_preset"));
  return true;
}

