void EditorPreviewController::setGradingShadowsHue(double value) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return;
  value = wrap_unit(value);
  if (qFuzzyCompare(grading_shadows_hue_ + 1.0, value + 1.0)) { return; }
  rememberStateForUndo();
  grading_shadows_hue_ = value;
  persistCurrentState();
  emit controlsChanged();
  submitGlobalToneColorEditIntent(QStringLiteral("grading_shadows_hue"));
}

