void EditorPreviewController::setActiveMaskIndex(int index) {
  const auto next_index = mask_session_.stack().isEmpty() || index < 0 ? -1
      : qBound(0, index, static_cast<int>(mask_session_.stack().size()) - 1);
  // Finish against the original target before a direct QML index change. The
  // higher-level selectMaskSet command already does this; property writes must too.
  if (next_index != mask_session_.activeIndex() && brush_stroke_active_)
    endActiveBrushStroke();
  if (!mask_session_.setActiveIndex(index)) {
    return;
  }
  invalidateActiveMaskCache();
  emit maskStateChanged();
  emit controlsChanged();
  emit maskOverlayChanged();
}

bool EditorPreviewController::selectMaskSet(const QString& set_id, const QString& component_id) {
  const auto index = mask_session_.indexForMaskSet(set_id, component_id);
  if (index < 0) return false;
  if (brushStrokeActive()) endActiveBrushStroke();
  setActiveMaskIndex(index);
  return true;
}

void EditorPreviewController::setActiveMaskName(const QString& name) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return;
  auto mask = activeMaskDefinition();
  if (mask.isEmpty()) {
    return;
  }
  const auto normalized_name = name.simplified();
  mask.insert(QStringLiteral("name"), normalized_name);
  if (is_selection_mask(mask)) {
    mask.insert(QStringLiteral("maskSetName"), normalized_name);
  }
  updateActiveMaskDefinition(mask);
}

