bool EditorPreviewController::sampleActiveDepthRangeAt(double normalized_x, double normalized_y) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  auto mask = activeMaskDefinition();
  if (mask.isEmpty() || activeMaskKind() != QStringLiteral("depth")) {
    return false;
  }
  if (!mask_has_valid_depth_payload(mask)) {
    setStatus(activeMaskDepthSamplingDisabledReason());
    return false;
  }

  const auto depth_data = mask.value(QStringLiteral("depthData")).toByteArray();
  const auto depth_width = mask.value(QStringLiteral("depthWidth")).toInt();
  const auto depth_height = mask.value(QStringLiteral("depthHeight")).toInt();
  const auto sample_x = qBound(
      0,
      static_cast<int>(qRound(qBound(0.0, normalized_x, 1.0) * static_cast<double>(depth_width - 1))),
      depth_width - 1);
  const auto sample_y = qBound(
      0,
      static_cast<int>(qRound(qBound(0.0, normalized_y, 1.0) * static_cast<double>(depth_height - 1))),
      depth_height - 1);
  const auto patch_radius = qBound(
      1,
      static_cast<int>(qRound(static_cast<double>(std::min(depth_width, depth_height)) * 0.015)),
      8);

  auto sample_min = 1.0;
  auto sample_max = 0.0;
  auto sample_sum = 0.0;
  auto sample_count = 0;
  for (auto y = std::max(0, sample_y - patch_radius);
       y <= std::min(depth_height - 1, sample_y + patch_radius);
       ++y) {
    for (auto x = std::max(0, sample_x - patch_radius);
         x <= std::min(depth_width - 1, sample_x + patch_radius);
         ++x) {
      const auto byte_index = y * depth_width + x;
      const auto depth = static_cast<unsigned char>(depth_data.at(byte_index)) / 255.0;
      sample_min = std::min(sample_min, depth);
      sample_max = std::max(sample_max, depth);
      sample_sum += depth;
      ++sample_count;
    }
  }

  if (sample_count <= 0) {
    setStatus(QStringLiteral("Unable to measure depth in the selected patch."));
    return false;
  }

  QVariantMap sample;
  sample.insert(QStringLiteral("x"), qBound(0.0, normalized_x, 1.0));
  sample.insert(QStringLiteral("y"), qBound(0.0, normalized_y, 1.0));
  sample.insert(QStringLiteral("depthMin"), clamp_unit(sample_min));
  sample.insert(QStringLiteral("depthMax"), clamp_unit(sample_max));
  sample.insert(QStringLiteral("depthMean"), clamp_unit(sample_sum / static_cast<double>(sample_count)));
  sample.insert(QStringLiteral("pixelCount"), sample_count);

  auto samples = mask.value(QStringLiteral("depthSamples")).toList();
  samples.append(sample);
  mask.insert(QStringLiteral("depthSamples"), normalized_depth_range_samples(samples));
  update_depth_range_constraints_from_samples(&mask);
  beginEditTransaction();
  updateActiveMaskDefinition(mask);
  endEditTransaction();
  setStatus(QStringLiteral("Depth range sample added."));
  return true;
}

