bool EditorPreviewController::syncPhotoLayerAdjustments(
    int source_index,
    const QVariantList& target_indices) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  if (source_index < 0 || source_index >= layer_session_.layers().size()) {
    return false;
  }
  const auto source_layer = layer_session_.layers().at(source_index).toMap();
  if (source_layer.value(QStringLiteral("kind")).toString() != QStringLiteral("adjustment")) {
    return false;
  }

  const auto recipe = photo_layer_adjustment_recipe(source_layer);
  const auto selected = normalized_photo_layer_indices(target_indices, layer_session_.layers().size());
  if (selected.isEmpty()) {
    return false;
  }

  auto next_layers = layer_session_.layers();
  auto changed = false;
  auto synced_count = 0;
  for (const auto target_index : selected) {
    if (target_index == source_index) {
      continue;
    }
    auto layer = next_layers.at(target_index).toMap();
    if (layer.value(QStringLiteral("locked")).toBool() ||
        layer.value(QStringLiteral("kind")).toString() != QStringLiteral("adjustment")) {
      continue;
    }
    if (replace_photo_layer_adjustment_recipe(&layer, recipe)) {
      next_layers[target_index] = layer;
      changed = true;
      ++synced_count;
    }
  }
  if (!changed || !applyPhotoLayerStackChange(next_layers)) {
    return false;
  }
  setStatus(
      QStringLiteral("Synced layer adjustments to %1 layer%2.")
          .arg(synced_count)
          .arg(synced_count == 1 ? QString() : QStringLiteral("s")));
  return true;
}

bool EditorPreviewController::setPhotoLayerClippingMask(int index, bool clipping_mask) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  if (index < 0 || index >= layer_session_.layers().size()) {
    return false;
  }
  auto next_layers = layer_session_.layers();
  auto layer = next_layers.at(index).toMap();
  if (layer.value(QStringLiteral("locked")).toBool() ||
      layer.value(QStringLiteral("kind")).toString() == QStringLiteral("group") ||
      (clipping_mask && index >= layer_session_.layers().size() - 1) ||
      layer.value(QStringLiteral("clippingMask")).toBool() == clipping_mask) {
    return false;
  }
  layer.insert(QStringLiteral("clippingMask"), clipping_mask);
  next_layers[index] = layer;
  return applyPhotoLayerStackChange(next_layers);
}

bool EditorPreviewController::setPhotoLayerMaskEnabled(int index, bool enabled) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  if (index < 0 || index >= layer_session_.layers().size()) {
    return false;
  }
  auto next_layers = layer_session_.layers();
  auto layer = next_layers.at(index).toMap();
  const auto has_mask =
      layer.value(QStringLiteral("selectionScoped")).toBool() ||
      layer.contains(QStringLiteral("maskData")) ||
      layer.value(QStringLiteral("maskWidth")).toInt() > 0;
  if (layer.value(QStringLiteral("locked")).toBool() || has_mask == enabled) {
    return false;
  }
  if (enabled) {
    layer.insert(QStringLiteral("maskData"), QByteArray(1, char(0xff)));
    layer.insert(QStringLiteral("maskWidth"), 1);
    layer.insert(QStringLiteral("maskHeight"), 1);
    layer.insert(QStringLiteral("maskInverted"), false);
    layer.insert(QStringLiteral("maskOpacity"), 1.0);
    layer.insert(QStringLiteral("maskDensity"), 1.0);
  } else {
    layer.remove(QStringLiteral("maskData"));
    layer.remove(QStringLiteral("maskWidth"));
    layer.remove(QStringLiteral("maskHeight"));
    layer.remove(QStringLiteral("maskInverted"));
    layer.remove(QStringLiteral("maskOpacity"));
    layer.remove(QStringLiteral("maskDensity"));
    layer.remove(QStringLiteral("selectionMaskSetId"));
    layer.remove(QStringLiteral("selectionMaskSetName"));
    layer.remove(QStringLiteral("selectionMaskSetIds"));
    layer.remove(QStringLiteral("selectionMaskSetNames"));
    layer.remove(QStringLiteral("selectionIntersectionMaskSetIds"));
    layer.remove(QStringLiteral("selectionIntersectionMaskSetNames"));
    layer.remove(QStringLiteral("selectionMaskSetCount"));
    layer.remove(QStringLiteral("selectionMaskSetSignature"));
    layer.insert(QStringLiteral("selectionScoped"), false);
  }
  next_layers[index] = layer;
  return applyPhotoLayerStackChange(next_layers);
}

bool EditorPreviewController::linkActiveSelectionToPhotoLayer(int index, bool inverted) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  if (index < 0 || index >= layer_session_.layers().size()) {
    return false;
  }
  const auto active_mask = activeMaskDefinition();
  if (!is_selection_mask(active_mask)) {
    setStatus(QStringLiteral("Create or select a selection before using it as a layer mask."));
    return false;
  }

  const auto target_id = layer_session_.layers().at(index).toMap().value(QStringLiteral("id")).toString();
  auto next_layers = layer_session_.layers();
  auto target_index = index;
  auto layer = next_layers.at(target_index).toMap();
  const auto kind = layer.value(QStringLiteral("kind")).toString().trimmed().toLower();
  if (layer.value(QStringLiteral("locked")).toBool() || kind == QStringLiteral("group") ||
      kind == QStringLiteral("adjustment")) {
    setStatus(QStringLiteral("Choose an unlocked image, pixel, fill, or text layer for the layer eraser."));
    return false;
  }

  const auto set_id = active_mask.value(QStringLiteral("maskSetId")).toString().simplified();
  const auto set_name = active_mask.value(QStringLiteral("maskSetName")).toString().simplified();
  if (set_id.isEmpty() && set_name.isEmpty()) {
    return false;
  }

  for (auto candidate_index = next_layers.size() - 1; candidate_index >= 0; --candidate_index) {
    const auto candidate = next_layers.at(candidate_index).toMap();
    if (candidate.value(QStringLiteral("id")).toString() == target_id ||
        candidate.value(QStringLiteral("kind")).toString() != QStringLiteral("adjustment") ||
        !candidate.value(QStringLiteral("name")).toString().startsWith(QStringLiteral("Selection Adjustment")) ||
        !selection_layer_matches_mask_set(candidate, set_id, set_name) ||
        !changed_photo_layer_adjustment_groups(candidate).isEmpty()) {
      continue;
    }
    next_layers.removeAt(candidate_index);
  }
  for (auto candidate_index = 0; candidate_index < next_layers.size(); ++candidate_index) {
    if (next_layers.at(candidate_index).toMap().value(QStringLiteral("id")).toString() == target_id) {
      target_index = candidate_index;
      break;
    }
  }

  layer = next_layers.at(target_index).toMap();
  layer.insert(QStringLiteral("selectionScoped"), true);
  layer.insert(QStringLiteral("selectionMaskSetId"), set_id);
  layer.insert(QStringLiteral("selectionMaskSetName"), set_name);
  layer.insert(QStringLiteral("selectionMaskSetIds"), string_list_to_variant_list(QStringList{set_id}));
  layer.insert(QStringLiteral("selectionMaskSetNames"), string_list_to_variant_list(QStringList{set_name}));
  layer.insert(QStringLiteral("maskInverted"), inverted);
  layer.insert(QStringLiteral("maskOpacity"), 1.0);
  layer.insert(QStringLiteral("maskDensity"), 1.0);
  layer.remove(QStringLiteral("maskData"));
  layer.remove(QStringLiteral("maskWidth"));
  layer.remove(QStringLiteral("maskHeight"));
  next_layers[target_index] = layer;
  if (!applyPhotoLayerStackChange(
          next_layers,
          QStringLiteral("photo_layer_mask"),
          false,
          QStringLiteral("Use selection as layer mask"))) {
    return false;
  }
  setStatus(inverted ? QStringLiteral("Layer eraser linked to the inverse selection.")
                     : QStringLiteral("Layer eraser linked to the active selection. Paint Add or Erase to refine it."));
  return true;
}

bool EditorPreviewController::setPhotoLayerMaskOpacity(int index, double opacity) {
  const auto customer_edit_scope = customer_edit_access_.enter();
  if (!customer_edit_scope) return {};
  if (index < 0 || index >= layer_session_.layers().size()) {
    return false;
  }
  auto next_layers = layer_session_.layers();
  auto layer = next_layers.at(index).toMap();
  const auto has_mask =
      layer.value(QStringLiteral("selectionScoped")).toBool() ||
      layer.contains(QStringLiteral("maskData")) ||
      layer.value(QStringLiteral("maskWidth")).toInt() > 0;
  if (layer.value(QStringLiteral("locked")).toBool() || !has_mask) {
    return false;
  }
  const auto next_opacity = qBound(0.0, opacity, 1.0);
  if (std::abs(layer.value(QStringLiteral("maskOpacity"), 1.0).toDouble() - next_opacity) <
      0.0001) {
    return false;
  }
  layer.insert(QStringLiteral("maskOpacity"), next_opacity);
  next_layers[index] = layer;
  return applyPhotoLayerStackChange(
      next_layers,
      QStringLiteral("photo_layer_stack"),
      false,
      QStringLiteral("Layer mask opacity change"));
}

