void EditorPreviewController::invalidateMaskDerivedCaches() {
  mask_group_cache_dirty_ = true;
  thumbnail_cache_session_.maskDirty() = true;
  thumbnail_cache_session_.maskDeferCounted() = false;
  thumbnail_cache_session_.maskSetsDeferredKey().clear();
  cached_mask_sets_.clear();
  cached_retouch_stack_.clear();
  invalidatePhotoLayerThumbnailCache();
  clearActiveMaskPreviewCache();
  invalidateActiveMaskCache();
}

void EditorPreviewController::invalidatePhotoLayerThumbnailCache() const {
  thumbnail_cache_session_.photoLayerDirty() = true;
  thumbnail_cache_session_.photoLayerDeferCounted() = false;
  ++thumbnail_cache_session_.photoLayerRevision();
}

void EditorPreviewController::scheduleThumbnailRefreshQueue(const QString& reason) const {
  if (!hasAsset() || (!thumbnail_cache_session_.maskDirty() && !thumbnail_cache_session_.photoLayerDirty())) {
    return;
  }

  const auto state_signature = thumbnail_state_signature(
      asset_id_,
      edit_intent_count_,
      mask_session_.workRevision(),
      thumbnail_cache_session_.photoLayerRevision());
  const auto queue_signature =
      QStringLiteral("%1|mask-revision:%2|mask-dirty:%3|layer-dirty:%4")
          .arg(state_signature,
               QString::number(mask_session_.workRevision()),
               thumbnail_cache_session_.maskDirty() ? QStringLiteral("true") : QStringLiteral("false"),
               thumbnail_cache_session_.photoLayerDirty() ? QStringLiteral("true") : QStringLiteral("false"));
  thumbnail_refresh_coordinator_.schedule(reason, queue_signature);
}

void EditorPreviewController::runQueuedThumbnailRefresh() {
  if (!thumbnail_refresh_coordinator_.pending()) {
    return;
  }

  if (thumbnailRefreshDeferred()) {
    thumbnail_refresh_coordinator_.defer();
    return;
  }

  if (thumbnail_refresh_coordinator_.workerRunning()) {
    return;
  }

  const auto generation = thumbnail_refresh_coordinator_.pendingGeneration();
  if (generation <= 0 || thumbnail_refresh_coordinator_.signature().isEmpty()) {
    thumbnail_refresh_coordinator_.clearPending();
    return;
  }

  const auto mask_sets_snapshot = thumbnail_presentation_service_.groupMaskSets(
      mask_session_.stack(), true);
  auto request = make_thumbnail_refresh_queue_request(ThumbnailRefreshQueueRequestFacts{
      .asset_id = asset_id_,
      .file_path = file_path_,
      .reason = thumbnail_refresh_coordinator_.reason(),
      .queue_signature = thumbnail_refresh_coordinator_.signature(),
      .state = currentState(),
      .published_preview_image = thumbnail_cache_session_.publishedPreviewImage(),
      .published_preview_state_signature =
          thumbnail_cache_session_.publishedPreviewStateSignature(),
      .photo_layers = layer_session_.layers(),
      .mask_stack = mask_session_.stack(),
      .mask_sets = mask_sets_snapshot,
      .generation = generation,
      .edit_intent_revision = edit_intent_count_,
      .mask_revision = mask_session_.workRevision(),
      .photo_layer_revision = thumbnail_cache_session_.photoLayerRevision(),
      .mask_thumbnail_dirty = thumbnail_cache_session_.maskDirty(),
      .photo_layer_thumbnail_dirty = thumbnail_cache_session_.photoLayerDirty(),
  });
  request.cancellation = thumbnail_refresh_coordinator_.activate(request.job.job_id);
  const auto renderers = make_thumbnail_worker_renderers(
      ThumbnailAdjustmentRendererDependencies{
          .shared_render = render_thumbnail_shared_preview_request,
      });
  thumbnail_refresh_coordinator_.startWorker(
      QtConcurrent::run([request, renderers]() {
        return compute_thumbnail_refresh_queue_result(request, renderers);
      }));
}

void EditorPreviewController::handleThumbnailRefreshQueueFinished() {
  const auto result = thumbnail_refresh_coordinator_.workerResult();
  thumbnail_refresh_coordinator_.recordWorkerCompleted();
  const auto expected_thumbnail_state_signature = thumbnail_state_signature(
      asset_id_,
      edit_intent_count_,
      mask_session_.workRevision(),
      thumbnail_cache_session_.photoLayerRevision());
  if (!thumbnail_refresh_coordinator_.resultIsCurrent(
          result,
          asset_id_,
          file_path_,
          expected_thumbnail_state_signature,
          mask_session_.workRevision())) {
    const auto has_superseding_pending_request =
        thumbnail_refresh_coordinator_.hasSupersedingPendingRequest(result);
    thumbnail_refresh_coordinator_.recordStaleResult(result);
    if (thumbnail_refresh_coordinator_.pending() &&
        !has_superseding_pending_request) {
      const auto retry_reason = result.request.reason.isEmpty()
                                    ? QStringLiteral("thumbnail_refresh_stale_retry")
                                    : result.request.reason;
      thumbnail_refresh_coordinator_.clearPending();
      scheduleThumbnailRefreshQueue(retry_reason);
    }
    if (thumbnail_refresh_coordinator_.pending()) {
      thumbnail_refresh_coordinator_.dispatchSoon();
    }
    return;
  }

  (void)publish_thumbnail_refresh_queue_entries(
      result,
      [this](const QString& cache_key, const QVariantMap& entry) {
        storeThumbnailEntryCache(cache_key, entry);
      });
  thumbnail_refresh_coordinator_.complete(result);
  emit controlsChanged();
}

QStringList EditorPreviewController::thumbnailRefreshDeferBlockers() const {
  // Visible preview publication outranks background thumbnail generation,
  // including the interval where a request is scheduled but has not started.
  return ThumbnailRefreshCoordinator::admissionBlockers({
      .full_preview_running = full_render_watcher_.isRunning() ||
                              render_scheduler_.fullActive() ||
                              full_request_pending_,
      .interactive_preview_running = interactive_render_watcher_.isRunning() ||
                                     render_scheduler_.interactiveActive() ||
                                     interactive_request_pending_,
      .coalesced_edit_active = history_service_.transactionActive(),
      .mask_refresh_suppressed = mask_thumbnail_refresh_suppressed_,
      .live_brush_stroke = brush_stroke_active_,
      .brush_commit_preview_points = !pending_brush_commit_preview_points_.isEmpty(),
      .brush_commit_scheduled = pending_brush_commit_scheduled_,
      .brush_commit_queued = !pending_brush_commits_.isEmpty(),
      .brush_raster_worker_running =
          mask_worker_coordinator_.brushRasterCommitWatcher().isRunning(),
      .brush_raster_commit_active = brush_raster_commit_active_,
      .layer_slider_debounce_active = photo_layer_adjustment_render_timer_.isActive(),
      .smart_selection_preview_requested =
          mask_worker_coordinator_.smartSelectPreviewPending(),
      .smart_selection_hover_active = smart_select_preview_timer_.isActive(),
      .smart_selection_preview_worker_running =
          mask_worker_coordinator_.smartSelectPreviewWatcher().isRunning(),
      .smart_selection_commit_pending = smart_select_commit_pending_,
      .smart_selection_commit_requested =
          mask_worker_coordinator_.smartSelectCommitPending(),
      .smart_selection_commit_worker_running =
          mask_worker_coordinator_.smartSelectCommitWatcher().isRunning(),
  });
}

bool EditorPreviewController::thumbnailRefreshDeferred() const {
  return !thumbnailRefreshDeferBlockers().isEmpty();
}

QVariantMap EditorPreviewController::thumbnailRefreshQueueFields() const {
  return thumbnail_refresh_coordinator_.fields(thumbnailRefreshDeferBlockers());
}

