void EditorPreviewController::synchronizeMaskState() {
  static_cast<void>(mask_session_.normalizeActiveIndex());

  const auto linear_index = firstMaskIndexForKind(QStringLiteral("linear"));
  if (linear_index >= 0) {
    const auto linear_mask = maskDefinitionAt(linear_index);
    linear_mask_enabled_ = map_bool_value(linear_mask, QStringLiteral("enabled"), false);
    linear_mask_exposure_ = map_double_value(linear_mask, QStringLiteral("exposure"), 0.0);
    linear_mask_temperature_ = map_double_value(linear_mask, QStringLiteral("temperature"), 0.0);
    linear_mask_feather_ = map_double_value(linear_mask, QStringLiteral("feather"), 0.22);
    linear_mask_position_ = map_double_value(linear_mask, QStringLiteral("position"), 0.5);
    linear_mask_rotation_ = map_double_value(linear_mask, QStringLiteral("rotation"), 0.0);
  } else {
    linear_mask_enabled_ = false;
    linear_mask_exposure_ = 0.0;
    linear_mask_temperature_ = 0.0;
    linear_mask_feather_ = 0.22;
    linear_mask_position_ = 0.5;
    linear_mask_rotation_ = 0.0;
  }

  const auto radial_index = firstMaskIndexForKind(QStringLiteral("radial"));
  if (radial_index >= 0) {
    const auto radial_mask = maskDefinitionAt(radial_index);
    radial_mask_enabled_ = map_bool_value(radial_mask, QStringLiteral("enabled"), false);
    radial_mask_exposure_ = map_double_value(radial_mask, QStringLiteral("exposure"), 0.0);
    radial_mask_temperature_ = map_double_value(radial_mask, QStringLiteral("temperature"), 0.0);
    radial_mask_feather_ = map_double_value(radial_mask, QStringLiteral("feather"), 0.25);
    radial_mask_center_x_ = map_double_value(radial_mask, QStringLiteral("centerX"), 0.5);
    radial_mask_center_y_ = map_double_value(radial_mask, QStringLiteral("centerY"), 0.5);
    radial_mask_radius_x_ = map_double_value(radial_mask, QStringLiteral("radiusX"), 0.25);
    radial_mask_radius_y_ = map_double_value(radial_mask, QStringLiteral("radiusY"), 0.25);
    radial_mask_rotation_ = map_double_value(radial_mask, QStringLiteral("rotation"), 0.0);
  } else {
    radial_mask_enabled_ = false;
    radial_mask_exposure_ = 0.0;
    radial_mask_temperature_ = 0.0;
    radial_mask_feather_ = 0.25;
    radial_mask_center_x_ = 0.5;
    radial_mask_center_y_ = 0.5;
    radial_mask_radius_x_ = 0.25;
    radial_mask_radius_y_ = 0.25;
    radial_mask_rotation_ = 0.0;
  }
}

bool EditorPreviewController::applyMaskStackChange(
    const QVariantList& stack,
    int active_index,
    bool rerender,
    const QString& operation,
    bool ensure_selection_adjustment_layer) {
  QElapsedTimer mask_stack_timer;
  mask_stack_timer.start();
  auto normalized_stack = normalized_mask_edit_stack(stack, mask_session_.stack());
  for (auto index = 0; index < normalized_stack.size(); ++index) {
    auto mask = normalized_stack.at(index).toMap();
    insert_brush_alpha_source_fields(&mask, mask, {}, &mask_session_);
    insert_shape_alpha_source_fields(&mask, mask);
    insert_generated_alpha_source_fields(&mask, mask);
    normalized_stack[index] = mask;
  }
  const auto normalize_elapsed_ms = mask_stack_timer.elapsed();
  for (const auto& value : normalized_stack) {
    const auto validation_error = normalized_mask_definition_write_error(value.toMap());
    if (!validation_error.isEmpty()) {
      setStatus(QStringLiteral("Rejected invalid mask source: %1.").arg(validation_error));
      return false;
    }
  }
  const auto validation_elapsed_ms = mask_stack_timer.elapsed();
  const auto normalized_active_index =
      normalized_stack.isEmpty() || active_index < 0
          ? -1
          : qBound(0, active_index, static_cast<int>(normalized_stack.size()) - 1);
  const auto selection_adjustment_layer_needed = [&]() {
    if (!ensure_selection_adjustment_layer || brush_stroke_suspends_side_effects_ ||
        normalized_active_index < 0 || normalized_active_index >= normalized_stack.size()) {
      return false;
    }
    const auto active_mask = normalized_stack.at(normalized_active_index).toMap();
    if (!is_selection_mask(active_mask)) {
      return false;
    }
    const auto active_set_id = active_mask.value(QStringLiteral("maskSetId")).toString().simplified();
    const auto active_set_name = active_mask.value(QStringLiteral("maskSetName")).toString().simplified();
    for (const auto& value : layer_session_.layers()) {
      const auto layer = value.toMap();
      if (selection_layer_matches_mask_set(layer, active_set_id, active_set_name)) {
        return false;
      }
    }
    return true;
  }();
  if (normalized_stack == mask_session_.stack() && normalized_active_index == mask_session_.activeIndex() &&
      !selection_adjustment_layer_needed) {
    return false;
  }

  const ScopedBoolValue defer_thumbnail_refresh(mask_thumbnail_refresh_suppressed_, true);
  if (!brush_stroke_suspends_side_effects_) {
    rememberStateForUndo();
  }
  const auto undo_elapsed_ms = mask_stack_timer.elapsed();
  if (selection_adjustment_layer_needed) {
    const auto active_mask = normalized_stack.at(normalized_active_index).toMap();
    auto next_layers = layer_session_.layers();
    auto layer = adjustment_layer_from_state(
        EditState{},
        QStringLiteral("Selection Adjustment %1").arg(next_layers.size() + 1),
        static_cast<int>(next_layers.size()) + 1);
    layer.insert(QStringLiteral("selectionScoped"), true);
    layer.insert(
        QStringLiteral("selectionMaskSetId"),
        active_mask.value(QStringLiteral("maskSetId")).toString());
    layer.insert(
        QStringLiteral("selectionMaskSetName"),
        active_mask.value(QStringLiteral("maskSetName")).toString());
    layer.insert(
        QStringLiteral("selectionMaskSetIds"),
        string_list_to_variant_list(QStringList{
            active_mask.value(QStringLiteral("maskSetId")).toString()}));
    layer.insert(
        QStringLiteral("selectionMaskSetNames"),
        string_list_to_variant_list(QStringList{
            active_mask.value(QStringLiteral("maskSetName")).toString()}));
    next_layers.prepend(layer);
    static_cast<void>(layer_session_.replaceLayers(normalized_photo_layers(next_layers)));
  }
  const auto layer_elapsed_ms = mask_stack_timer.elapsed();
  mask_session_.replaceStack(normalized_stack, normalized_active_index);
  const auto repaired_state =
      preset_state_without_dangling_mask_references(currentState(), true, true);
  if (repaired_state.layers != layer_session_.layers()) {
    static_cast<void>(layer_session_.replaceLayers(
        normalized_photo_layers(repaired_state.layers)));
    invalidatePhotoLayerThumbnailCache();
  }
  static_cast<void>(mask_session_.advanceWorkRevision());
  mask_worker_coordinator_.latestBrushRasterGeneration()->store(
      mask_session_.advanceBrushRasterGeneration(),
      std::memory_order_relaxed);
  invalidateMaskDerivedCaches();
  const auto cache_elapsed_ms = mask_stack_timer.elapsed();
  synchronizeMaskState();
  const auto sync_elapsed_ms = mask_stack_timer.elapsed();
  if (!brush_stroke_suspends_side_effects_) {
    persistCurrentState();
  }
  const auto persist_elapsed_ms = mask_stack_timer.elapsed();
  const auto lightweight_mask_notify =
      operation == QStringLiteral("selection_brush_start") || operation == QStringLiteral("lasso_sample");
  // Starting a tool changes mask/layer revisions. A cached or in-flight initial
  // render will then be rejected as stale. Keep the idle tool-start fast path,
  // but replace pending photograph work so loading cannot end on a blank frame.
  const auto refresh_loading_preview = lightweight_mask_notify &&
      (last_successful_preview_file_path_ != file_path_ ||
       render_scheduler_.interactiveActive() || render_scheduler_.fullActive() ||
       interactive_render_watcher_.isRunning() || full_render_watcher_.isRunning() ||
       interactive_request_pending_ || full_request_pending_);
  if (operation == QStringLiteral("lasso_sample")) {
    emit polygonPathChanged();
  } else {
    emit maskStateChanged();
  }
  const auto mask_state_elapsed_ms = mask_stack_timer.elapsed();
  // Starting a selection brush inserts a real child mask component. Layer-row
  // models expose those components through photoLayers(), whose notify signal
  // is controlsChanged; refresh that model even though the image render stays
  // on the lightweight tool-start path.
  if (!lightweight_mask_notify || operation == QStringLiteral("selection_brush_start")) {
    emit controlsChanged();
  }
  const auto controls_elapsed_ms = mask_stack_timer.elapsed();
  emit maskOverlayChanged();
  const auto overlay_elapsed_ms = mask_stack_timer.elapsed();
  if (rerender && (!lightweight_mask_notify || refresh_loading_preview)) {
    const auto resolved_operation =
        operation.isEmpty() ? QStringLiteral("mask_stack") : operation;
    const auto committed_mask_change =
        refresh_loading_preview || resolved_operation == QStringLiteral("smart_selection") ||
        is_local_mask_coverage_operation(resolved_operation);
    if (is_local_mask_color_operation(resolved_operation)) {
      // These controls change the photograph, not just a selection overlay.
      // Keep local effects in the draft and request settled/full quality.
      submitEditIntent(EditIntent{
          .operation = resolved_operation,
          .dirty_domain = QStringLiteral("local_adjustments"),
          .render_reason = QStringLiteral("edit_change"),
          .schedule_full_resolution = true,
      });
    } else {
      submitMaskRasterizationEditIntent(
          resolved_operation,
          committed_mask_change,
          committed_mask_change ? QStringLiteral("mask_commit")
                                : QStringLiteral("mask_preview_change"));
    }
  }
  const auto total_elapsed_ms = mask_stack_timer.elapsed();
  if (total_elapsed_ms >= 10) {
    observability::logInfo(
        photoEditorPerfLog(),
        QStringLiteral("preview.mask_stack_change.completed"),
        {
            {QStringLiteral("elapsed_ms"), total_elapsed_ms},
            {QStringLiteral("normalize_elapsed_ms"), normalize_elapsed_ms},
            {QStringLiteral("validation_elapsed_ms"), validation_elapsed_ms},
            {QStringLiteral("undo_elapsed_ms"), undo_elapsed_ms},
            {QStringLiteral("layer_elapsed_ms"), layer_elapsed_ms},
            {QStringLiteral("cache_elapsed_ms"), cache_elapsed_ms},
            {QStringLiteral("sync_elapsed_ms"), sync_elapsed_ms},
            {QStringLiteral("persist_elapsed_ms"), persist_elapsed_ms},
            {QStringLiteral("mask_state_elapsed_ms"), mask_state_elapsed_ms},
            {QStringLiteral("controls_elapsed_ms"), controls_elapsed_ms},
            {QStringLiteral("overlay_elapsed_ms"), overlay_elapsed_ms},
            {QStringLiteral("lightweight_mask_notify"), lightweight_mask_notify},
            {QStringLiteral("rerender"), rerender},
            {QStringLiteral("operation"), operation.isEmpty() ? QStringLiteral("mask_stack") : operation},
            {QStringLiteral("selection_adjustment_layer_needed"), selection_adjustment_layer_needed},
            {QStringLiteral("mask_count"), normalized_stack.size()},
            {QStringLiteral("active_index"), normalized_active_index},
        });
  }
  return true;
}

bool EditorPreviewController::applyPhotoLayerStackChange(
    const QVariantList& layers,
    const QString& operation,
    bool debounce_render,
    const QString& undo_label,
    bool record_undo) {
  QElapsedTimer total_timer;
  QElapsedTimer stage_timer;
  total_timer.start();
  stage_timer.start();
  // Layer thumbnails are refreshed by the background queue after publication.
  // Re-rasterizing every compressed paint tile here stalls the UI on long strokes.
  const auto normalized_layers = normalized_photo_layers(layers, true);
  const auto normalize_elapsed_ms = stage_timer.nsecsElapsed() / 1e6;
  if (normalized_layers == layer_session_.layers()) {
    return false;
  }
  stage_timer.restart();
  if (record_undo)
    rememberStateForUndo(undo_label.trimmed().isEmpty() ? QStringLiteral("Layer stack change") : undo_label);
  const auto undo_elapsed_ms = stage_timer.nsecsElapsed() / 1e6;
  stage_timer.restart();
  static_cast<void>(layer_session_.replaceLayers(normalized_layers));
  const auto replace_elapsed_ms = stage_timer.nsecsElapsed() / 1e6;
  stage_timer.restart();
  invalidatePhotoLayerThumbnailCache();
  const auto cache_elapsed_ms = stage_timer.nsecsElapsed() / 1e6;
  stage_timer.restart();
  persistCurrentState();
  const auto persist_elapsed_ms = stage_timer.nsecsElapsed() / 1e6;
  stage_timer.restart();
  scheduleControlsChanged();
  if (debounce_render) {
    schedulePhotoLayerAdjustmentRender();
  } else {
    photo_layer_adjustment_render_timer_.stop();
    photo_layer_adjustment_render_burst_started_msecs_ = 0;
    photo_layer_adjustment_render_pending_write_count_ = 0;
    submitLayerCompositeEditIntent(
        operation.isEmpty() ? QStringLiteral("photo_layer_stack") : operation,
        false,
        QStringLiteral("photo_layer_change"));
  }
  const auto intent_elapsed_ms = stage_timer.nsecsElapsed() / 1e6;
  const auto total_elapsed_ms = total_timer.nsecsElapsed() / 1e6;
  qsizetype paint_tile_count = 0;
  for (const auto& value : normalized_layers) {
    paint_tile_count += value.toMap().value(QStringLiteral("paintTiles"))
        .toMap().value(QStringLiteral("tiles")).toMap().size();
  }
  last_photo_layer_stack_performance_ = {
      {QStringLiteral("operation"), operation},
      {QStringLiteral("layer_count"), normalized_layers.size()},
      {QStringLiteral("paint_tile_count"), paint_tile_count},
      {QStringLiteral("total_elapsed_ms"), total_elapsed_ms},
      {QStringLiteral("normalize_elapsed_ms"), normalize_elapsed_ms},
      {QStringLiteral("undo_elapsed_ms"), undo_elapsed_ms},
      {QStringLiteral("replace_elapsed_ms"), replace_elapsed_ms},
      {QStringLiteral("cache_elapsed_ms"), cache_elapsed_ms},
      {QStringLiteral("persist_elapsed_ms"), persist_elapsed_ms},
      {QStringLiteral("intent_elapsed_ms"), intent_elapsed_ms},
  };
  if (total_elapsed_ms >= 10.0 || operation == QStringLiteral("paint_stroke")) {
    observability::logInfo(photoEditorPerfLog(),
        QStringLiteral("preview.photo_layer_stack_change.completed"),
        last_photo_layer_stack_performance_);
  }
  return true;
}

bool EditorPreviewController::applyPhotoLayerMetadataChange(
    const QVariantList& layers,
    const QStringList& changed_keys,
    const QString& undo_label) {
  if (layers == layer_session_.layers() || layers.size() != layer_session_.layers().size()) {
    return false;
  }

  rememberStateForUndo(
      undo_label.trimmed().isEmpty() ? QStringLiteral("Layer metadata change") : undo_label);
  static_cast<void>(layer_session_.replaceLayers(layers));

  // Rename/lock changes do not alter pixels. Keep the rendered thumbnail
  // fields and update only the row metadata so the Layers panel responds
  // immediately without scheduling image or thumbnail work.
  if (thumbnail_cache_session_.photoLayersWithThumbnails().size() == layer_session_.layers().size()) {
    for (auto index = 0; index < layer_session_.layers().size(); ++index) {
      const auto source = layer_session_.layers().at(index).toMap();
      auto cached = thumbnail_cache_session_.photoLayersWithThumbnails().at(index).toMap();
      if (cached.value(QStringLiteral("id")).toString() !=
          source.value(QStringLiteral("id")).toString()) {
        continue;
      }
      for (const auto& key : changed_keys) {
        if (source.contains(key)) {
          cached.insert(key, source.value(key));
        } else {
          cached.remove(key);
        }
      }
      thumbnail_cache_session_.photoLayersWithThumbnails()[index] = cached;
    }
  }

  persistCurrentState();
  scheduleControlsChanged();
  return true;
}

bool EditorPreviewController::updateMaskAt(
    int index,
    const QVariantMap& mask,
    bool rerender,
    bool allow_locked,
    const QString& operation) {
  if (index < 0 || index >= mask_session_.stack().size()) {
    return false;
  }
  const auto existing_mask = mask_session_.stack().at(index).toMap();
  if (!allow_locked && map_bool_value(existing_mask, QStringLiteral("locked"), false)) {
    return false;
  }
  auto next_stack = mask_session_.stack();
  auto normalized_mask = normalized_mask_edit_definition(mask, existing_mask, index + 1);
  insert_brush_alpha_source_fields(&normalized_mask, normalized_mask, {}, &mask_session_);
  insert_shape_alpha_source_fields(&normalized_mask, normalized_mask);
  insert_generated_alpha_source_fields(&normalized_mask, normalized_mask);
  next_stack[index] = normalized_mask;

  // Brush Refine owns local paint and refinement state. Copying its selection
  // adjustments onto the generated parent changes the entire matte, including
  // pixels outside the painted strokes.
  const auto is_local_brush_refinement =
      map_bool_value(normalized_mask, QStringLiteral("brushRefineMode"), false);
  if (is_selection_mask(normalized_mask) && !is_local_brush_refinement) {
    const auto set_id = normalized_mask.value(QStringLiteral("maskSetId")).toString();
    for (int sibling_index = 0; sibling_index < next_stack.size(); ++sibling_index) {
      if (sibling_index == index) {
        continue;
      }
      auto sibling_mask = next_stack.at(sibling_index).toMap();
      if (!is_selection_mask(sibling_mask) ||
          sibling_mask.value(QStringLiteral("maskSetId")).toString() != set_id) {
        continue;
      }
      copy_selection_adjustments_to_mask(&sibling_mask, normalized_mask);
      next_stack[sibling_index] = sibling_mask;
    }
  }
  return applyMaskStackChange(
      next_stack,
      mask_session_.activeIndex(),
      rerender,
      operation.isEmpty()
          ? mask_edit_operation_for_change(existing_mask, normalized_mask)
          : operation,
      true);
}

bool EditorPreviewController::updateActiveMaskDefinition(
    const QVariantMap& mask,
    bool rerender,
    bool allow_locked,
    const QString& operation) {
  return updateMaskAt(mask_session_.activeIndex(), mask, rerender, allow_locked, operation);
}

bool EditorPreviewController::updateLegacyKindMask(const QString& kind, const QVariantMap& updates) {
  const auto normalized_kind = normalized_mask_kind(kind);
  auto index = firstMaskIndexForKind(normalized_kind);
  auto next_stack = mask_session_.stack();
  QVariantMap mask;
  if (index >= 0) {
    mask = next_stack.at(index).toMap();
  } else {
    index = static_cast<int>(next_stack.size());
    mask = default_mask_definition(normalized_kind, index + 1);
    next_stack.append(mask);
  }

  for (auto it = updates.cbegin(); it != updates.cend(); ++it) {
    mask.insert(it.key(), it.value());
  }
  next_stack[index] = normalized_mask_definition(mask, index + 1);
  return applyMaskStackChange(
      next_stack,
      index,
      true,
      mask_edit_operation_for_change(maskDefinitionAt(index), next_stack.at(index).toMap()),
      true);
}

QString EditorPreviewController::presetsFilePath() const {
  return QDir(AppBootstrap::appDataLocation()).filePath(QStringLiteral("editor-presets.json"));
}

QString EditorPreviewController::cameraDefaultsFilePath() const {
  return QDir(AppBootstrap::appDataLocation()).filePath(QStringLiteral("camera-defaults.json"));
}

QString EditorPreviewController::customCropPresetsFilePath() const {
  return QDir(AppBootstrap::appDataLocation()).filePath(QStringLiteral("custom-crop-presets.json"));
}

QString EditorPreviewController::editHistorySnapshotsFilePath() const {
  return QDir(AppBootstrap::appDataLocation())
      .filePath(QStringLiteral("edit-history-snapshots.json"));
}

void EditorPreviewController::loadEditHistorySnapshots() {
  history_service_.replaceSnapshots(
      load_edit_history_snapshots(editHistorySnapshotsFilePath()));
}

void EditorPreviewController::saveEditHistorySnapshots() const {
  save_edit_history_snapshots(
      editHistorySnapshotsFilePath(),
      history_service_.snapshots());
}

void EditorPreviewController::loadCustomCropPresets() {
  custom_crop_presets_.clear();
  QFile file(customCropPresetsFilePath());
  if (!file.exists() || !file.open(QIODevice::ReadOnly)) {
    return;
  }
  const auto document = QJsonDocument::fromJson(file.readAll());
  if (!document.isObject()) {
    return;
  }
  const auto preset_array = document.object().value(QStringLiteral("presets")).toArray();
  for (const auto& value : preset_array) {
    const auto normalized = normalized_custom_crop_preset(value.toString());
    if (!normalized.isEmpty() &&
        !built_in_crop_aspect_presets().contains(normalized, Qt::CaseInsensitive) &&
        !custom_crop_presets_.contains(normalized, Qt::CaseInsensitive)) {
      custom_crop_presets_.push_back(normalized);
    }
  }
}

void EditorPreviewController::saveCustomCropPresets() const {
  const QFileInfo destination_info(customCropPresetsFilePath());
  QDir().mkpath(destination_info.dir().absolutePath());
  QJsonArray preset_array;
  for (const auto& preset : custom_crop_presets_) {
    preset_array.push_back(preset);
  }
  QJsonObject root;
  root.insert(QStringLiteral("presets"), preset_array);
  QSaveFile file(customCropPresetsFilePath());
  if (!file.open(QIODevice::WriteOnly)) {
    return;
  }
  file.write(QJsonDocument(root).toJson(QJsonDocument::Indented));
  file.commit();
}

void EditorPreviewController::loadPresets() {
  preset_service_.replaceBuiltIns(
      built_in_preset_map(),
      built_in_preset_pack_map(),
      built_in_preset_category_map(),
      built_in_preset_group_map(),
      built_in_preset_adaptive_rule_map());
  for (auto iterator =
           preset_service_.builtInPresets().cbegin();
       iterator !=
       preset_service_.builtInPresets().cend();
       ++iterator) {
    preset_service_.setBuiltInContract(
        iterator.key(),
        normalized_preset_contract(
            QJsonObject{
                {QStringLiteral(
                     "presetVersion"),
                 1},
                {QStringLiteral(
                     "sourceRenderer"),
                 QStringLiteral(
                     "aces2-ocio-v1")},
                {QStringLiteral(
                     "migrationTarget"),
                 QStringLiteral(
                     "photo-editor-edit-recipe-v13.1")},
            },
            iterator.value(),
            true));
  }
  preset_service_.clearUsers();

  QFile file(presetsFilePath());
  if (!file.exists() || !file.open(QIODevice::ReadOnly)) {
    return;
  }

  const auto document = QJsonDocument::fromJson(file.readAll());
  if (!document.isObject()) {
    return;
  }

  const auto preset_array = document.object().value(QStringLiteral("presets")).toArray();
  for (const auto& preset_value : preset_array) {
    if (!preset_value.isObject()) {
      continue;
    }

    const auto preset_object = preset_value.toObject();
    const auto name = normalizedPresetName(preset_object.value(QStringLiteral("name")).toString());
    const auto pack = preset_object.value(QStringLiteral("pack")).toString(QStringLiteral("User Presets")).simplified();
    const auto category =
        normalized_preset_category(preset_object.value(QStringLiteral("category")).toString(), pack);
    const auto stored = parse_stored_adjustment_state(
        preset_object, AdjustmentPatchScope::SourceAgnostic);
    if (name.isEmpty() || !stored.state.has_value()) {
      continue;
    }

    const auto& preset_state = *stored.state;
    const auto adaptive_rules = preset_object.value(QStringLiteral("adaptiveRules")).toArray();
    preset_service_.upsertUser(
        name,
        preset_state,
        pack.isEmpty() ? QStringLiteral("User Presets") : pack,
        category,
        stored.groups.isEmpty()
            ? declared_preset_groups_for_state(preset_state)
            : stored.groups,
        adaptive_rules,
        normalized_preset_contract(preset_object, preset_state));
  }

  const auto favorite_array = document.object().value(QStringLiteral("favorites")).toArray();
  for (const auto& favorite_value : favorite_array) {
    const auto name = normalizedPresetName(favorite_value.toString());
    if (!name.isEmpty()) {
      static_cast<void>(preset_service_.setFavorite(name, true));
    }
  }
}

bool EditorPreviewController::savePresets(QString* error) const {
  const QFileInfo destination_info(presetsFilePath());
  if (!QDir().mkpath(destination_info.dir().absolutePath())) {
    if (error != nullptr) {
      *error = QStringLiteral("Could not create the preset library folder at %1.")
                   .arg(destination_info.dir().absolutePath());
    }
    return false;
  }

  QJsonArray preset_array;
  for (auto iterator = preset_service_.userPresets().cbegin(); iterator != preset_service_.userPresets().cend(); ++iterator) {
    QJsonObject preset_object;
    preset_object.insert(QStringLiteral("name"), iterator.key());
    preset_object.insert(
        QStringLiteral("pack"),
        preset_service_.userPacks().value(iterator.key(), QStringLiteral("User Presets")));
    preset_object.insert(
        QStringLiteral("category"),
        preset_service_.userCategories().value(
            iterator.key(),
            normalized_preset_category(
                preset_service_.userPacks().value(iterator.key(), QStringLiteral("User Presets")),
                QStringLiteral("User"))));
    preset_object.insert(
        QStringLiteral("adjustmentGroups"),
        preset_adjustment_groups_to_json(
            preset_service_.userGroups().value(iterator.key(), declared_preset_groups_for_state(iterator.value()))));
    const auto adaptive_rules = preset_service_.userAdaptiveRules().value(iterator.key());
    if (!adaptive_rules.isEmpty()) {
      preset_object.insert(QStringLiteral("adaptiveRules"), adaptive_rules);
    }
    insert_preset_contract_fields(
        &preset_object,
        preset_service_.userContracts().value(
            iterator.key(),
            normalized_preset_contract(
                {},
                iterator.value())));
    preset_object.insert(QStringLiteral("adjustmentPatch"),
        serialize_adjustment_patch(
            iterator.value(),
            preset_service_.userGroups().value(
                iterator.key(),
                declared_preset_groups_for_state(iterator.value())),
            AdjustmentPatchScope::SourceAgnostic));
    preset_array.push_back(preset_object);
  }

  QJsonArray favorite_array;
  for (const auto& name : favoritePresetNames()) {
    favorite_array.push_back(name);
  }

  QJsonObject root;
  root.insert(
      QStringLiteral("format"),
      QStringLiteral("photo-editor-user-presets"));
  root.insert(QStringLiteral("version"), 3);
  root.insert(QStringLiteral("presets"), preset_array);
  root.insert(QStringLiteral("favorites"), favorite_array);

  QSaveFile file(presetsFilePath());
  if (!file.open(QIODevice::WriteOnly)) {
    if (error != nullptr) {
      *error = QStringLiteral("Could not save the preset library at %1: %2")
                   .arg(presetsFilePath(), file.errorString());
    }
    return false;
  }

  const auto payload = QJsonDocument(root).toJson(QJsonDocument::Indented);
  if (file.write(payload) != payload.size() || !file.commit()) {
    if (error != nullptr) {
      *error = QStringLiteral("Could not finish saving the preset library at %1: %2")
                   .arg(presetsFilePath(), file.errorString());
    }
    return false;
  }
  return true;
}

void EditorPreviewController::loadCameraDefaults() {
  preset_service_.clearCameraDefaults();

  QFile file(cameraDefaultsFilePath());
  if (!file.exists() || !file.open(QIODevice::ReadOnly)) {
    return;
  }

  const auto document = QJsonDocument::fromJson(file.readAll());
  if (!document.isObject()) {
    return;
  }

  const auto defaults = document.object().value(QStringLiteral("cameraDefaults")).toArray();
  for (const auto& value : defaults) {
    if (!value.isObject()) {
      continue;
    }
    const auto object = value.toObject();
    const auto key = normalizedCameraDefaultKey(object.value(QStringLiteral("cameraLabel")).toString());
    const auto stored = parse_stored_adjustment_state(
        object, AdjustmentPatchScope::CameraBound);
    if (key.isEmpty() || !stored.state.has_value()) {
      continue;
    }
    preset_service_.setCameraDefault(key, *stored.state);
  }
}

void EditorPreviewController::saveCameraDefaults() const {
  const QFileInfo destination_info(cameraDefaultsFilePath());
  QDir().mkpath(destination_info.dir().absolutePath());

  QJsonArray defaults_array;
  for (auto iterator = preset_service_.cameraDefaults().cbegin(); iterator != preset_service_.cameraDefaults().cend(); ++iterator) {
    QJsonObject default_object;
    default_object.insert(QStringLiteral("cameraLabel"), iterator.key());
    default_object.insert(QStringLiteral("adjustmentPatch"),
        serialize_adjustment_patch(
            iterator.value(),
            {QStringLiteral("raw"), QStringLiteral("tone"),
             QStringLiteral("color"), QStringLiteral("detail")},
            AdjustmentPatchScope::CameraBound));
    defaults_array.push_back(default_object);
  }

  QJsonObject root;
  root.insert(QStringLiteral("format"), QStringLiteral("photo-editor-camera-defaults"));
  root.insert(QStringLiteral("version"), 2);
  root.insert(QStringLiteral("cameraDefaults"), defaults_array);

  QSaveFile file(cameraDefaultsFilePath());
  if (!file.open(QIODevice::WriteOnly)) {
    return;
  }

  file.write(QJsonDocument(root).toJson(QJsonDocument::Indented));
  file.commit();
}

void EditorPreviewController::reportRecipeSaveFailure(const QString& detail) {
  recipe_save_error_ = detail;
  emit recipeSaveStateChanged();
  observability::logWarning(photoEditorPreviewLog(), QStringLiteral("recipe.save.failed"), {
      {QStringLiteral("error"), detail},
      {QStringLiteral("retry_delay_ms"), recipe_save_retry_delay_ms_},
  });
  if (recipe_save_queue_.pending() && !recipe_close_paused_) {
    persist_timer_.start(recipe_save_retry_delay_ms_);
    recipe_save_retry_delay_ms_ = std::min(60000, recipe_save_retry_delay_ms_ * 2);
  }
}

void EditorPreviewController::flushPersistedState() {
  if (recipe_close_paused_) return;
  if (recipe_preparation_active_ || persist_process_.state() != QProcess::NotRunning) {
    return;
  }
  const auto* snapshot = recipe_save_queue_.begin();
  if (snapshot == nullptr) return;
  if (!checkpointRecipeSaves()) {
    recipe_save_queue_.complete(false);
    reportRecipeSaveFailure(recipe_save_error_);
    return;
  }
  const auto request = *snapshot;
  const auto app_data_root = AppBootstrap::appDataLocation();
  recipe_preparation_active_ = true;
  emit recipeSaveStateChanged();
  struct PreparationResult final {
    PreparedEditorRecipePersistence prepared;
    qint64 elapsed_ms = 0;
  };
  auto* watcher = new QFutureWatcher<PreparationResult>(this);
  connect(watcher, &QFutureWatcher<PreparationResult>::finished, this,
          [this, watcher, request] {
    const auto result = watcher->result();
    watcher->deleteLater();
    recipe_preparation_active_ = false;
    if (recipe_close_paused_) {
      // Close retains the durable outbox; a prepared helper must not restart
      // persistence after the close workflow has paused it.
      recipe_save_queue_.complete(false);
      checkpointRecipeSaves();
      emit recipeSaveStateChanged();
      return;
    }
    completeRecipePreparation(request, result.prepared, result.elapsed_ms);
    emit recipeSaveStateChanged();
  });
  watcher->setFuture(QtConcurrent::run([request, app_data_root] {
    QElapsedTimer timer; timer.start();
    const auto provenance = resolve_decoder_provenance_for_source(request.file_path, request.state);
    const auto migration = request.migration_evidence.value(QStringLiteral("migrationPending")).toBool();
    auto prepared = prepare_editor_recipe_persistence_payload(
        request.asset_id, request.state, provenance, request.migration_evidence, app_data_root, migration);
    return PreparationResult{std::move(prepared), timer.elapsed()};
  }));
}

void EditorPreviewController::completeRecipePreparation(
    const EditorRecipeSaveSnapshot& snapshot,
    const PreparedEditorRecipePersistence& prepared,
    qint64 preparation_elapsed_ms) {
  const auto snapshot_asset_id = snapshot.asset_id;
  const auto snapshot_migration_evidence = snapshot.migration_evidence;
  const auto migration_acceptance = snapshot.migration_evidence
                                        .value(QStringLiteral("migrationPending")).toBool();
  QString error;
  QVariantMap receipt_context;
  auto persistence = prepared;
  bool admitted = true;
  if (prepared.ok() && !snapshot.agent_task_id.isEmpty()) {
    receipt_context = {{QStringLiteral("taskId"), snapshot.agent_task_id},
        {QStringLiteral("assetId"), snapshot.asset_id},
        {QStringLiteral("sourceOwner"), QStringLiteral("preview")},
        {QStringLiteral("attemptId"), QUuid::createUuid().toString(QUuid::WithoutBraces)},
        {QStringLiteral("nativeRecipe"), serialize_adjustment_patch_json(snapshot.state,
            all_adjustment_groups(), AdjustmentPatchScope::AssetBound)},
        {QStringLiteral("payload"), prepared.payload}};
    const auto guard = agent_recipe_persistence_handler_
        ? agent_recipe_persistence_handler_(QStringLiteral("guard"), receipt_context)
        : QVariantMap{{QStringLiteral("ok"), false}, {QStringLiteral("error"),
            QStringLiteral("Recover the owning agent task before saving its pending revision.")}};
    admitted = guard.value(QStringLiteral("ok")).toBool() &&
        !guard.value(QStringLiteral("payload")).toByteArray().isEmpty();
    if (!admitted) {
      error = guard.value(QStringLiteral("error")).toString();
      if (error.isEmpty()) error = QStringLiteral("The owning task did not return an exact recipe commit guard.");
    }
    else {
      persistence.payload = guard.value(QStringLiteral("payload")).toByteArray();
      receipt_context.insert(QStringLiteral("payload"), persistence.payload);
      const auto admission = agent_recipe_persistence_handler_(QStringLiteral("prepare"), receipt_context);
      admitted = admission.value(QStringLiteral("ok")).toBool();
      if (!admitted) error = admission.value(QStringLiteral("error")).toString();
      else agent_recipe_persistence_context_ = receipt_context;
    }
  }
  const auto started = admitted && start_prepared_editor_recipe_persistence(
      &persist_process_, persistence, QDir::currentPath(), &error);
  if (!started && !agent_recipe_persistence_context_.isEmpty()) {
    auto context = std::exchange(agent_recipe_persistence_context_, {});
    context.insert(QStringLiteral("ok"), false);
    static_cast<void>(agent_recipe_persistence_handler_(QStringLiteral("finished"), context));
  }
  observability::logInfo(photoEditorPreviewLog(), QStringLiteral("recipe.save.prepared"), {
      {QStringLiteral("workflow"), QStringLiteral("recipe_save")},
      {QStringLiteral("stage"), QStringLiteral("prepare_and_start")},
      {QStringLiteral("asset_id"), snapshot_asset_id},
      {QStringLiteral("elapsed_ms"), preparation_elapsed_ms},
      {QStringLiteral("started"), started},
      {QStringLiteral("helper_pid"), persist_process_.processId()},
  });
  if (!started && !recipe_save_queue_.activeAssetId().isEmpty()) {
    // FailedToStart can be delivered synchronously by the launcher. Its signal
    // handler has already requeued and reported that failure.
    constexpr auto canonical_validation_prefix =
        "Edit cannot be represented by canonical recipe v13:";
    if (error.startsWith(QString::fromLatin1(canonical_validation_prefix))) {
      const auto failed_asset = recipe_save_queue_.activeAssetId();
      recipe_save_queue_.rejectActive();
      const auto checkpoint_ok = checkpointRecipeSaves();
      recipe_save_error_ =
          QStringLiteral("Edits for %1 could not be saved because the recipe is invalid. "
                         "The complete edit was preserved for recovery; saves for other photos will continue.")
              .arg(failed_asset);
      if (!checkpoint_ok && !recipe_save_error_.isEmpty())
        recipe_save_error_ += QStringLiteral(" The recovery checkpoint could not be updated.");
      observability::logWarning(photoEditorPreviewLog(),
          QStringLiteral("recipe.save.quarantined"), {
              {QStringLiteral("asset_id"), failed_asset},
              {QStringLiteral("error"), error},
              {QStringLiteral("recovery_preserved"), checkpoint_ok},
          });
      emit recipeSaveStateChanged();
      if (recipe_save_queue_.pending() && !recipe_close_paused_)
        persist_timer_.start(0);
    } else {
      recipe_save_queue_.complete(false);
      checkpointRecipeSaves();
      reportRecipeSaveFailure(error);
    }
  } else if (migration_acceptance && snapshot_asset_id == asset_id_ &&
             snapshot_migration_evidence == rendering_upgrade_evidence_) {
    rendering_upgrade_evidence_.clear();
    emit controlsChanged();
  }
}

bool EditorPreviewController::hasVisibleAdjustments() const {
  return has_visible_adjustments(currentState());
}

bool EditorPreviewController::decodeSourceImage(QImage* image, int max_edge) const {
  return decode_source_image(file_path_, image, max_edge, currentState());
}

QSize EditorPreviewController::sourceImageSize() const {
  // QML reads crop geometry and source dimensions many times per edit. Do not
  // reopen a RAW decoder for each property read. Keep one entry per controller
  // and invalidate it when the path, file size, or modification time changes.
  const QFileInfo source(file_path_);
  const auto path = source.absoluteFilePath();
  const auto bytes = source.size();
  const auto modified_ms = source.lastModified().toMSecsSinceEpoch();
  if (source.exists() && source_size_cache_.isValid() &&
      source_size_cache_path_ == path && source_size_cache_bytes_ == bytes &&
      source_size_cache_modified_ms_ == modified_ms) {
    return source_size_cache_;
  }
  ++source_size_cache_misses_;
  source_size_cache_path_ = path;
  source_size_cache_bytes_ = bytes;
  source_size_cache_modified_ms_ = modified_ms;
  source_size_cache_ = source_image_size_for_file(file_path_);
  return source_size_cache_;
}

QImage EditorPreviewController::applyCrop(const QImage& image) const {
  return apply_crop(image, currentState());
}

void EditorPreviewController::updateRawClippingWarnings(const QImage& image) {
  const auto raw_clipping = raw_clipping_stats_for_image(image);
  histogram_scope_session_.updateRawClipping(
      raw_clipping.sample_count,
      raw_clipping.shadow_clip_count,
      raw_clipping.highlight_clip_count);
  emit histogramChanged();
}

QSize EditorPreviewController::activeBrushLivePreviewSize() const {
  const auto source_size = activeMaskDefinition().value(QStringLiteral("toolRole")).toString() == QStringLiteral("retouch")
      ? sourceImageSize() : crop_rect_for_image(sourceImageSize(), currentState()).size();
  if (!source_size.isValid()) {
    return {};
  }
  const auto requested_edge =
      preview_viewport_active_ && preview_viewport_patch_max_edge_ > 0
          ? preview_viewport_patch_max_edge_
          : interactive_preview_edge_for_state(currentState(), previewTargetEdge());
  const auto preview_edge = qBound(
      kMinimumInteractivePreviewEdge,
      std::max(requested_edge, kBrushLivePreviewMinimumEdge),
      kMaximumInteractivePreviewEdge);
  return scaled_size_for_max_edge(source_size, preview_edge);
}

void EditorPreviewController::updateActiveBrushLivePreview(
    const QVector<BrushPreviewPoint>& sampled_points) {
  if (sampled_points.isEmpty()) return;
  // A bounded raster supplies immediate pointer feedback. Keep the larger,
  // higher-fidelity matte off the UI thread and coalesce point batches.
  pending_brush_live_preview_points_ += sampled_points;
  active_brush_live_preview_backend_ = activeMaskBrushAutoMask()
      ? QStringLiteral("cpu-auto-mask") : QStringLiteral("cpu-brush-raster");
  dispatchBrushLivePreview();
}

void EditorPreviewController::dispatchBrushLivePreview() {
  if (brush_live_preview_running_ || pending_brush_live_preview_points_.isEmpty() ||
      !brush_stroke_active_ || activeMaskKind() != QStringLiteral("brush")) return;
  auto points = std::exchange(pending_brush_live_preview_points_, {});
  const auto size = activeBrushLivePreviewSize();
  auto frame = active_brush_live_preview_frame_;
  if (frame.raster.image.size() != size) { points = active_brush_live_points_; frame.point_count = 0; }
  frame.generation = brush_live_preview_generation_->load();
  frame.auto_mask = activeMaskBrushAutoMask();
  const auto generation = brush_live_preview_generation_;
  const auto path = file_path_;
  const auto state = currentState();
  const auto mask = activeMaskDefinition();
  const auto style = activeBrushPreviewStyle();
  const auto auto_mask = frame.auto_mask;
  const auto tolerance = activeMaskBrushAutoMaskTolerance();
  const auto protect_edges = activeMaskBrushProtectEdges();
  brush_live_preview_running_ = true;
  active_brush_live_preview_backend_ = auto_mask
      ? QStringLiteral("cpu-auto-mask") : QStringLiteral("cpu-brush-raster");
  auto_mask_live_preview_watcher_.setFuture(QtConcurrent::run(&brush_live_preview_worker_pool(),
      [frame = std::move(frame), points = std::move(points), size, generation,
       path, state, style, auto_mask, tolerance, protect_edges]() mutable {
    QElapsedTimer timer;
    timer.start();
    const photo_editor::pipeline::CancellationToken cancellation{generation.get(), frame.generation};
    if (cancellation.cancelled()) return frame;
    if (auto_mask && !frame.source_attempted) {
      frame.source_attempted = true;
      (void)decode_source_image(path, &frame.source, std::max(size.width(), size.height()), state);
      if (style.circular && !frame.source.isNull()) frame.source = apply_crop(frame.source, state);
    }
    if (!cancellation.cancelled())
      frame.raster.append(size, points, style,
          auto_mask && !frame.source.isNull() ? &frame.source : nullptr,
          tolerance, protect_edges, cancellation);
    frame.point_count += points.size();
    frame.elapsed_ms = timer.elapsed();
    return frame;
  }));
}

void EditorPreviewController::clearActiveBrushLivePreview() {
  ++*brush_live_preview_generation_;
  pending_brush_live_preview_points_.clear();
  active_brush_live_preview_frame_ = {};
  active_brush_live_preview_image_ = QImage{};
  active_brush_live_preview_backend_ = QStringLiteral("none");
  active_brush_live_preview_elapsed_ms_ = 0;
  active_brush_live_preview_within_latency_budget_ = true;
  active_brush_live_preview_fallback_reason_.clear();
  if (image_provider_ != nullptr) {
    image_provider_->clearImage(QString::fromLatin1(kActiveBrushLivePreviewImageId));
  }
  if (brush_preview_compositor_ != nullptr) {
    brush_preview_compositor_->clear(&active_brush_live_preview_image_);
  }
  ++active_brush_live_preview_revision_;
}

void EditorPreviewController::updateDiagnosticOverlayImages(
    const QImage& image,
    const QImage& proof_gamut_warning_mask) {
  // Retain the explicit synchronous renderer contract for reference callers.
  // App publication and user actions dispatch through queueDiagnosticOverlayUpdate.
  if (image_provider_ == nullptr || image.isNull()) {
    clearDiagnosticOverlayImages();
    return;
  }
  cancelDiagnosticOverlayUpdate();
  auto overlays = build_diagnostic_overlay_images(image, proof_gamut_warning_mask, !soft_proof_enabled_);
  if (overlays.focus_check.isNull()) {
    clearDiagnosticOverlayImages();
    return;
  }
  publishDiagnosticOverlayImages(DiagnosticOverlayResult{
      .images = {std::move(overlays.focus_check), std::move(overlays.focus_peaking),
                 std::move(overlays.clipping), std::move(overlays.false_color),
                 std::move(overlays.gamut), std::move(overlays.zone_map)},
      .revision = diagnostic_overlay_revision_,
  });
}

void EditorPreviewController::publishDiagnosticOverlayImages(const DiagnosticOverlayResult& result) {
  if (image_provider_ == nullptr) return;
  image_provider_->setImage(QString::fromLatin1(kFocusCheckOverlayImageId), result.images[0]);
  image_provider_->setImage(QString::fromLatin1(kFocusPeakingOverlayImageId), result.images[1]);
  image_provider_->setImage(QString::fromLatin1(kClippingOverlayImageId), result.images[2]);
  image_provider_->setImage(QString::fromLatin1(kFalseColorOverlayImageId), result.images[3]);
  image_provider_->setImage(QString::fromLatin1(kGamutOverlayImageId), result.images[4]);
  image_provider_->setImage(QString::fromLatin1(kZoneMapOverlayImageId), result.images[5]);

  focus_check_overlay_source_ = withDisplayRevision(
      QStringLiteral("image://editor-preview/%1").arg(QString::fromLatin1(kFocusCheckOverlayImageId)));
  focus_peaking_overlay_source_ = withDisplayRevision(
      QStringLiteral("image://editor-preview/%1").arg(QString::fromLatin1(kFocusPeakingOverlayImageId)));
  clipping_overlay_source_ = withDisplayRevision(
      QStringLiteral("image://editor-preview/%1").arg(QString::fromLatin1(kClippingOverlayImageId)));
  false_color_overlay_source_ = withDisplayRevision(
      QStringLiteral("image://editor-preview/%1").arg(QString::fromLatin1(kFalseColorOverlayImageId)));
  gamut_overlay_source_ = withDisplayRevision(
      QStringLiteral("image://editor-preview/%1").arg(QString::fromLatin1(kGamutOverlayImageId)));
  zone_map_overlay_source_ = withDisplayRevision(
      QStringLiteral("image://editor-preview/%1").arg(QString::fromLatin1(kZoneMapOverlayImageId)));
  emit diagnosticOverlaysChanged();
}

void EditorPreviewController::scheduleDiagnosticOverlayUpdate(
    const QImage& image,
    int generation,
    const QImage& proof_gamut_warning_mask) {
  if (!preview_session_.isCurrent(generation) && image != pixel_inspector_preview_image_) return;
  queueDiagnosticOverlayUpdate(image, proof_gamut_warning_mask, {}, true);
}

void EditorPreviewController::cancelDiagnosticOverlayUpdate() {
  ++diagnostic_overlay_revision_;
  if (diagnostic_overlay_cancellation_) diagnostic_overlay_cancellation_->store(true, std::memory_order_relaxed);
  diagnostic_overlay_timer_.stop();
  diagnostic_overlay_pending_ = false;
  diagnostic_overlay_pending_image_ = {};
  diagnostic_overlay_pending_gamut_mask_ = {};
  diagnostic_overlay_pending_surface_.reset();
}

void EditorPreviewController::queueDiagnosticOverlayUpdate(
    const QImage& image, const QImage& proof_gamut_warning_mask,
    std::shared_ptr<const photo_editor::pipeline::metal::MetalOutputSurface> surface,
    bool deferred) {
  if (!diagnostic_overlays_requested_ || image_provider_ == nullptr ||
      (image.isNull() && surface == nullptr)) return;
  cancelDiagnosticOverlayUpdate();
  diagnostic_overlay_pending_ = true;
  diagnostic_overlay_pending_image_ = image;
  diagnostic_overlay_pending_gamut_mask_ = proof_gamut_warning_mask;
  diagnostic_overlay_pending_surface_ = std::move(surface);
  if (deferred) diagnostic_overlay_timer_.start(kDeferredDiagnosticOverlayDelayMs);
  else startDiagnosticOverlayUpdate();
}

void EditorPreviewController::startDiagnosticOverlayUpdate() {
  if (!diagnostic_overlay_pending_ || diagnostic_overlay_active_ ||
      !diagnostic_overlays_requested_ || image_provider_ == nullptr) return;
  if (processing_) {
    diagnostic_overlay_timer_.start(kDeferredDiagnosticOverlayDelayMs);
    return;
  }
  diagnostic_overlay_pending_ = false;
  diagnostic_overlay_active_ = true;
  auto image = std::move(diagnostic_overlay_pending_image_);
  auto gamut_mask = std::move(diagnostic_overlay_pending_gamut_mask_);
  auto surface = std::move(diagnostic_overlay_pending_surface_);
  const auto revision = diagnostic_overlay_revision_;
  const auto heuristic_gamut = !soft_proof_enabled_;
  const auto cancellation = std::make_shared<std::atomic_bool>(false);
  diagnostic_overlay_cancellation_ = cancellation;
  diagnostic_overlay_watcher_.setFuture(QtConcurrent::run(
      [image = std::move(image), gamut_mask = std::move(gamut_mask),
       surface = std::move(surface), revision, heuristic_gamut, cancellation]() mutable {
    auto result = DiagnosticOverlayResult{.revision = revision};
    QElapsedTimer timer;
    timer.start();
    qint64 readback_bytes = 0;
    const auto record_work = qScopeGuard([&]() {
      if (!observability::enabled()) return;
      observability::logInfo(photoEditorPerfLog(), QStringLiteral("editor.diagnostics.render"),
          {{QStringLiteral("readback_bytes"), readback_bytes},
           {QStringLiteral("width"), image.width()}, {QStringLiteral("height"), image.height()},
           {QStringLiteral("cancelled"), cancellation->load(std::memory_order_relaxed)},
           {QStringLiteral("readback_failed"), result.readback_failed},
           {QStringLiteral("elapsed_ms"), timer.elapsed()}});
    });
    if (cancellation->load(std::memory_order_relaxed)) return result;
    if (image.isNull() && surface != nullptr) {
#if defined(PHOTO_EDITOR_HAS_METAL_BACKEND) && PHOTO_EDITOR_HAS_METAL_BACKEND
      image = QImage(surface->width(), surface->height(), QImage::Format_ARGB32);
      if (image.isNull() || !surface->copy_bgra8_region(
              0, 0, image.width(), image.height(),
              std::span<std::uint8_t>(image.bits(), static_cast<std::size_t>(image.sizeInBytes())))) {
        result.readback_failed = !cancellation->load(std::memory_order_relaxed);
        return result;
      }
      readback_bytes = image.sizeInBytes();
#else
      result.readback_failed = true;
      return result;
#endif
    }
    if (cancellation->load(std::memory_order_relaxed)) return result;
    auto overlays = build_diagnostic_overlay_images(image, gamut_mask, heuristic_gamut, cancellation);
    if (cancellation->load(std::memory_order_relaxed)) return result;
    result.images = {std::move(overlays.focus_check), std::move(overlays.focus_peaking),
                     std::move(overlays.clipping), std::move(overlays.false_color),
                     std::move(overlays.gamut), std::move(overlays.zone_map)};
    return result;
  }));
}

void EditorPreviewController::clearDiagnosticOverlayImages() {
  cancelDiagnosticOverlayUpdate();
  if (image_provider_ != nullptr) {
    image_provider_->clearImage(QString::fromLatin1(kFocusCheckOverlayImageId));
    image_provider_->clearImage(QString::fromLatin1(kFocusPeakingOverlayImageId));
    image_provider_->clearImage(QString::fromLatin1(kClippingOverlayImageId));
    image_provider_->clearImage(QString::fromLatin1(kFalseColorOverlayImageId));
    image_provider_->clearImage(QString::fromLatin1(kGamutOverlayImageId));
    image_provider_->clearImage(QString::fromLatin1(kZoneMapOverlayImageId));
  }
  focus_check_overlay_source_.clear();
  focus_peaking_overlay_source_.clear();
  clipping_overlay_source_.clear();
  false_color_overlay_source_.clear();
  gamut_overlay_source_.clear();
  zone_map_overlay_source_.clear();
  diagnostic_overlay_rendered_cache_key_.clear();
  emit diagnosticOverlaysChanged();
}

void EditorPreviewController::resetSmartSelectPreview() {
  static_cast<void>(mask_session_.advanceSmartPreviewGeneration());
  smart_select_preview_timer_.stop();
  mask_worker_coordinator_.markSmartSelectPreviewDispatched();
  mask_worker_coordinator_.latestSmartSelectPreviewJob() = {};
  smart_select_commit_pending_ = false;
  smart_select_commit_intent_.clear();
  smart_select_commit_create_new_ = false;
  clearSmartSelectPreviewState();
}

void EditorPreviewController::startSmartSelectPreviewRequest() {
  if (!mask_worker_coordinator_.smartSelectPreviewPending() || mask_worker_coordinator_.smartSelectPreviewWatcher().isRunning()) {
    return;
  }

  const auto request = mask_worker_coordinator_.pendingSmartSelectPreview();
  mask_worker_coordinator_.markSmartSelectPreviewDispatched();
  const auto preview_result_current = [this](const SmartSelectPreviewResult& result) {
    const auto& job = result.job;
    return !job.job_id.isEmpty() &&
           job.job_id == mask_worker_coordinator_.latestSmartSelectPreviewJob().job_id &&
           job.generation == mask_session_.smartPreviewGeneration() &&
           job.asset_id == asset_id_ &&
           job.file_path == file_path_ &&
           job.state_signature == edit_state_signature(currentState());
  };
  if (!vision_segmentation_available() && !aiSmartSelectionAvailable()) {
    const auto result = compute_smart_select_preview_result(request);
    const auto current = preview_result_current(result);
    if (result.success && current) {
      updateSmartSelectPreviewState(result.preview_mask, result.instance_ids);
      if (smart_select_path_has_spatial_constraints(smart_select_preview_prompts_))
        setStatus(QStringLiteral("Selection preview ready. Review the boundary, then choose Use selection."));
    } else if (!current) {
      mask_session_.recordSmartSelectionCancellation();
      recordCancelledMaskWork(
          QStringLiteral("smart_selection_preview"),
          result.generation,
          mask_session_.smartPreviewGeneration(),
          result.job.state_revision,
          QStringLiteral("stale_result"),
          QStringLiteral("preview_publish"),
          {},
          {},
          {},
          result.job);
    } else if (!result.success &&
               !mask_worker_coordinator_.smartSelectPreviewPending()) {
      resetSmartSelectPreview();
      if (!result.error_message.isEmpty()) setStatus(result.error_message);
    }
    if (mask_worker_coordinator_.smartSelectPreviewPending() && !smart_select_preview_timer_.isActive()) {
      startSmartSelectPreviewRequest();
    }
    if (thumbnail_refresh_coordinator_.pending()) {
      thumbnail_refresh_coordinator_.dispatchSoon();
    }
    return;
  }
  mask_worker_coordinator_.smartSelectPreviewWatcher().setFuture(
      QtConcurrent::run([request]() { return compute_smart_select_preview_result(request); }));
}

void EditorPreviewController::handleSmartSelectPreviewFinished() {
  const auto result = mask_worker_coordinator_.smartSelectPreviewWatcher().result();
  const auto& job = result.job;
  const auto current =
      !job.job_id.isEmpty() &&
      job.job_id == mask_worker_coordinator_.latestSmartSelectPreviewJob().job_id &&
      job.generation == mask_session_.smartPreviewGeneration() &&
      job.asset_id == asset_id_ &&
      job.file_path == file_path_ &&
      job.state_signature == edit_state_signature(currentState());
  if (result.success && current) {
    updateSmartSelectPreviewState(result.preview_mask, result.instance_ids);
    if (smart_select_path_has_spatial_constraints(smart_select_preview_prompts_))
      setStatus(QStringLiteral("Selection preview ready. Review the boundary, then choose Use selection."));
  } else if (!current) {
    mask_session_.recordSmartSelectionCancellation();
    recordCancelledMaskWork(
        QStringLiteral("smart_selection_preview"),
        result.generation,
        mask_session_.smartPreviewGeneration(),
        job.state_revision,
        QStringLiteral("stale_result"),
        QStringLiteral("preview_publish"),
        {},
        {},
        {},
        job);
  } else if (!result.success &&
             !mask_worker_coordinator_.smartSelectPreviewPending()) {
    resetSmartSelectPreview();
    if (!result.error_message.isEmpty()) setStatus(result.error_message);
  }

  if (mask_worker_coordinator_.smartSelectPreviewPending() && !smart_select_preview_timer_.isActive()) {
    startSmartSelectPreviewRequest();
  }
  if (thumbnail_refresh_coordinator_.pending()) {
    thumbnail_refresh_coordinator_.dispatchSoon();
  }
}

void EditorPreviewController::startSmartSelectCommitRequest() {
  if (!mask_worker_coordinator_.smartSelectCommitPending() || mask_worker_coordinator_.smartSelectCommitWatcher().isRunning()) {
    return;
  }

  const auto request = mask_worker_coordinator_.pendingSmartSelectCommit();
  mask_worker_coordinator_.markSmartSelectCommitDispatched();
  mask_worker_coordinator_.smartSelectCommitWatcher().setFuture(
      QtConcurrent::run([request]() { return compute_smart_select_commit_result(request); }));
  updateProcessingState();
}

void EditorPreviewController::handleSmartSelectCommitFinished() {
  const auto result = mask_worker_coordinator_.smartSelectCommitWatcher().result();
  publishSmartSelectCommitResult(result);
  if (mask_worker_coordinator_.smartSelectCommitPending()) {
    startSmartSelectCommitRequest();
  } else {
    updateProcessingState();
  }
}

void EditorPreviewController::publishSmartSelectCommitResult(
    const SmartSelectCommitResult& result) {
  // Only a previously admitted internal job reaches this completion callback.
  const auto customer_edit_scope = customer_edit_access_.restore();
  const auto& request = result.request;
  const auto& job = request.job;
  const auto stale =
      job.job_id.isEmpty() ||
      job.job_id != mask_worker_coordinator_.latestSmartSelectCommitJob().job_id ||
      job.generation != mask_session_.smartSelectionGeneration() ||
      job.state_revision != mask_session_.workRevision() ||
      job.asset_id != asset_id_ ||
      job.file_path != file_path_ ||
      job.state_signature != edit_state_signature(currentState()) ||
      request.generation != job.generation ||
      request.state_revision != job.state_revision ||
      request.asset_id != job.asset_id ||
      request.file_path != job.file_path;
  if (stale) {
    mask_session_.recordSmartSelectionCancellation();
    recordCancelledMaskWork(
        QStringLiteral("smart_selection"),
        request.generation,
        mask_session_.smartSelectionGeneration(),
        request.state_revision,
        QStringLiteral("stale_result"),
        QStringLiteral("async_commit_publish"),
        {},
        {},
        {},
        job);
    setSelectionFailureReason(QStringLiteral("cancelled"));
    setStatus(QStringLiteral("Smart selection canceled because the image or selection changed."));
    return;
  }

  const auto runtime_label = QStringLiteral("Local Smart Select");
  const auto prompt_count = request.points.size();
  if (!result.decode_success) {
    qWarning() << "pickMaskPath: failed to decode source image";
    const auto failure_status =
        QStringLiteral("Unable to decode the source image for smart selection.");
    setSelectionFailureReason(QStringLiteral("decode-failed"));
    rememberSmartSelectionRetry(
        request.points,
        request.intent,
        request.create_new,
        failure_status);
    setStatus(failure_status);
    auto telemetry = QVariantMap{
        {QStringLiteral("operation"), QStringLiteral("smart_selection")},
        {QStringLiteral("async_worker"), true},
        {QStringLiteral("smart_selection_worker_thread"), result.worker_thread},
        {QStringLiteral("smart_selection_ms"), result.elapsed_ms},
        {QStringLiteral("generated_mask_feedback_budget_ms"),
         kCachedGeneratedMaskFeedbackLatencyBudgetMs},
        {QStringLiteral("generated_mask_feedback_elapsed_ms"), result.elapsed_ms},
        {QStringLiteral("generated_mask_feedback_cached"), false},
        {QStringLiteral("generated_mask_feedback_within_latency_budget"),
         result.elapsed_ms <= kCachedGeneratedMaskFeedbackLatencyBudgetMs},
        {QStringLiteral("prompt_count"), prompt_count},
        {QStringLiteral("runtime_label"), runtime_label},
        {QStringLiteral("success"), false},
        {QStringLiteral("cancelled"), false},
        {QStringLiteral("job_generation"), request.generation},
        {QStringLiteral("state_revision"), request.state_revision},
        {QStringLiteral("cache_hit"), false},
        {QStringLiteral("fallback_reason"), failure_status},
    };
    insert_async_mask_job_fields(&telemetry, job);
    recordMaskWorkTelemetry(telemetry);
    return;
  }

  const auto normalized_points = normalized_smart_select_path(request.points);
  const auto& segmentation_result = result.segmentation_result;
  if (!segmentation_result.success) {
    resetSmartSelectPreview();
    const auto failure_status = actionable_segmentation_failure_status(
        runtime_label,
        request.intent == QStringLiteral("remove")
            ? QStringLiteral("retouch target")
            : QStringLiteral("selection"),
        segmentation_result,
        !normalized_points.isEmpty());
    setSelectionFailureReason(
        segmentation_failure_reason_code(segmentation_result, !normalized_points.isEmpty()));
    rememberSmartSelectionRetry(
        request.points,
        request.intent,
        request.create_new,
        failure_status);
    if (request.intent != QStringLiteral("remove") && !normalized_points.isEmpty()) {
      const auto selection_operation = pick_intent_mask_operation(request.intent);
      auto next_stack = mask_session_.stack();
      auto mask_def = default_mask_definition(
          normalized_points.size() >= 3 ? QStringLiteral("lasso") : QStringLiteral("ellipse"),
          static_cast<int>(next_stack.size()) + 1);
      mask_def.insert(
          QStringLiteral("name"),
          normalized_points.size() >= 3
              ? QStringLiteral("Rough Smart Lasso %1").arg(next_stack.size() + 1)
              : QStringLiteral("Rough Smart Ellipse %1").arg(next_stack.size() + 1));
      mask_def.insert(QStringLiteral("operation"), selection_operation);
      mask_def.insert(QStringLiteral("committed"), true);
      QVariantMap fallback_metadata;
      fallback_metadata.insert(QStringLiteral("smartFallback"), true);
      fallback_metadata.insert(QStringLiteral("smartFallbackRuntime"), runtime_label);
      fallback_metadata.insert(QStringLiteral("smartFallbackReason"), failure_status);
      mask_def.insert(QStringLiteral("generatedMaskMetadata"), fallback_metadata);
      if (!request.create_new && hasActiveMask()) {
        const auto active_mask = activeMaskDefinition();
        if (is_selection_mask(active_mask)) {
          inherit_selection_mask_set(&mask_def, active_mask);
        }
      }

      if (normalized_points.size() >= 3) {
        QVariantList polygon_points;
        polygon_points.reserve(normalized_points.size());
        for (const auto& point : normalized_points) {
          QVariantMap polygon_point;
          polygon_point.insert(QStringLiteral("x"), qBound(0.0, point.x(), 1.0));
          polygon_point.insert(QStringLiteral("y"), qBound(0.0, point.y(), 1.0));
          polygon_points.append(polygon_point);
        }
        mask_def.insert(QStringLiteral("polygonPoints"), polygon_points);
        mask_def.insert(QStringLiteral("lassoRawPoints"), polygon_points);
        mask_def.insert(QStringLiteral("feather"), 0.06);
      } else {
        auto min_x = normalized_points.constFirst().x();
        auto max_x = min_x;
        auto min_y = normalized_points.constFirst().y();
        auto max_y = min_y;
        for (const auto& point : normalized_points) {
          min_x = std::min(min_x, point.x());
          max_x = std::max(max_x, point.x());
          min_y = std::min(min_y, point.y());
          max_y = std::max(max_y, point.y());
        }
        const auto center_x = qBound(0.0, (min_x + max_x) * 0.5, 1.0);
        const auto center_y = qBound(0.0, (min_y + max_y) * 0.5, 1.0);
        const auto radius_x = qBound(0.05, std::max(0.08, (max_x - min_x) * 0.65), 0.5);
        const auto radius_y = qBound(0.05, std::max(0.08, (max_y - min_y) * 0.65), 0.5);
        mask_def.insert(QStringLiteral("centerX"), center_x);
        mask_def.insert(QStringLiteral("centerY"), center_y);
        mask_def.insert(QStringLiteral("radiusX"), radius_x);
        mask_def.insert(QStringLiteral("radiusY"), radius_y);
        mask_def.insert(QStringLiteral("rotation"), 0.0);
        mask_def.insert(QStringLiteral("feather"), 0.08);
      }
      static_cast<void>(
          merge_smart_select_prompt_metadata(&mask_def, request.points));
      next_stack.append(mask_def);
      applyMaskStackChange(
          next_stack,
          static_cast<int>(next_stack.size()) - 1,
          true,
          QStringLiteral("smart_selection"),
          true);
      setStatus(QStringLiteral("%1 Created an editable rough selection fallback for refinement.")
                    .arg(failure_status));
      auto fallback_telemetry = QVariantMap{
          {QStringLiteral("operation"), QStringLiteral("smart_selection")},
          {QStringLiteral("async_worker"), true},
          {QStringLiteral("smart_selection_worker_thread"), result.worker_thread},
          {QStringLiteral("smart_selection_ms"), result.elapsed_ms},
          {QStringLiteral("generated_mask_feedback_budget_ms"),
           kCachedGeneratedMaskFeedbackLatencyBudgetMs},
          {QStringLiteral("generated_mask_feedback_elapsed_ms"), result.elapsed_ms},
          {QStringLiteral("generated_mask_feedback_cached"), false},
          {QStringLiteral("generated_mask_feedback_within_latency_budget"),
           result.elapsed_ms <= kCachedGeneratedMaskFeedbackLatencyBudgetMs},
          {QStringLiteral("prompt_count"), prompt_count},
          {QStringLiteral("runtime_label"), runtime_label},
          {QStringLiteral("success"), false},
          {QStringLiteral("cancelled"), false},
          {QStringLiteral("job_generation"), request.generation},
          {QStringLiteral("state_revision"), request.state_revision},
          {QStringLiteral("cache_hit"), false},
          {QStringLiteral("fallback_created"), true},
          {QStringLiteral("fallback_reason"), failure_status},
      };
      insert_async_mask_job_fields(&fallback_telemetry, job);
      insert_mask_alpha_trace_fields(
          &fallback_telemetry,
          mask_def,
          mask_tile_source_revision(
              request.file_path,
              request.state,
              raster_size_for_mask_trace(mask_def)),
          raster_size_for_mask_trace(mask_def));
      recordMaskWorkTelemetry(fallback_telemetry);
      return;
    }

    setStatus(failure_status);
    auto telemetry = QVariantMap{
        {QStringLiteral("operation"), QStringLiteral("smart_selection")},
        {QStringLiteral("async_worker"), true},
        {QStringLiteral("smart_selection_worker_thread"), result.worker_thread},
        {QStringLiteral("smart_selection_ms"), result.elapsed_ms},
        {QStringLiteral("generated_mask_feedback_budget_ms"),
         kCachedGeneratedMaskFeedbackLatencyBudgetMs},
        {QStringLiteral("generated_mask_feedback_elapsed_ms"), result.elapsed_ms},
        {QStringLiteral("generated_mask_feedback_cached"), false},
        {QStringLiteral("generated_mask_feedback_within_latency_budget"),
         result.elapsed_ms <= kCachedGeneratedMaskFeedbackLatencyBudgetMs},
        {QStringLiteral("prompt_count"), prompt_count},
        {QStringLiteral("runtime_label"), runtime_label},
        {QStringLiteral("success"), false},
        {QStringLiteral("cancelled"), false},
        {QStringLiteral("job_generation"), request.generation},
        {QStringLiteral("state_revision"), request.state_revision},
        {QStringLiteral("cache_hit"), false},
        {QStringLiteral("fallback_created"), false},
        {QStringLiteral("fallback_reason"), failure_status},
    };
    insert_async_mask_job_fields(&telemetry, job);
    recordMaskWorkTelemetry(telemetry);
    return;
  }

  clearMaskActionRetry();
  updateSmartSelectPreviewResult(segmentation_result);
  const auto selection_operation = pick_intent_mask_operation(request.intent);
  QVariantMap published_mask;
  const auto pick_result =
      request.intent == QStringLiteral("remove")
          ? pickObjectRemoveMask(
                segmentation_result,
                request.create_new,
                result.source_image,
                runtime_label,
                request.points,
                &published_mask)
          : pickObjectSelectionMask(
                segmentation_result,
                selection_operation,
                request.create_new,
                result.source_image,
                runtime_label,
                request.points,
                &published_mask);
  auto telemetry = QVariantMap{
      {QStringLiteral("operation"), QStringLiteral("smart_selection")},
      {QStringLiteral("async_worker"), true},
      {QStringLiteral("smart_selection_worker_thread"), result.worker_thread},
      {QStringLiteral("smart_selection_ms"), result.elapsed_ms},
      {QStringLiteral("generated_mask_feedback_budget_ms"),
       kCachedGeneratedMaskFeedbackLatencyBudgetMs},
      {QStringLiteral("generated_mask_feedback_elapsed_ms"), result.elapsed_ms},
      {QStringLiteral("generated_mask_feedback_cached"), false},
      {QStringLiteral("generated_mask_feedback_within_latency_budget"),
       result.elapsed_ms <= kCachedGeneratedMaskFeedbackLatencyBudgetMs},
      {QStringLiteral("prompt_count"), prompt_count},
      {QStringLiteral("runtime_label"), runtime_label},
      {QStringLiteral("success"), pick_result != QStringLiteral("error")},
      {QStringLiteral("cancelled"), false},
      {QStringLiteral("job_generation"), request.generation},
      {QStringLiteral("state_revision"), request.state_revision},
      {QStringLiteral("cache_hit"), false},
      {QStringLiteral("fallback_reason"), QString()},
  };
  insert_async_mask_job_fields(&telemetry, job);
  if (pick_result != QStringLiteral("error")) {
    insert_mask_alpha_trace_fields(
        &telemetry,
        published_mask,
        mask_tile_source_revision(
            request.file_path,
            request.state,
            raster_size_for_mask_trace(published_mask)),
        raster_size_for_mask_trace(published_mask));
    setSelectionFailureReason({});
  } else {
    setSelectionFailureReason(QStringLiteral("unknown"));
  }
  recordMaskWorkTelemetry(telemetry);
}

void EditorPreviewController::updateSmartSelectPreviewState(
    const QVariantMap& preview_mask,
    const QVector<int>& instance_ids,
    const QVector<int>& candidate_instance_ids) {
  auto traced_preview_mask = preview_mask;
  if (!traced_preview_mask.isEmpty()) {
    const auto raster_size = raster_size_for_mask_trace(traced_preview_mask);
    insert_mask_alpha_trace_fields(
        &traced_preview_mask,
        traced_preview_mask,
        mask_tile_source_revision(file_path_, currentState(), raster_size),
        raster_size);
  }
  const auto normalized_candidate_index = candidate_instance_ids.isEmpty()
                                               ? 0
                                               : (candidate_instance_ids ==
                                                          smart_select_preview_candidate_instance_ids_
                                                     ? qBound(
                                                           0,
                                                           smart_select_preview_candidate_index_,
                                                           static_cast<int>(candidate_instance_ids.size()) - 1)
                                                     : 0);
  if (smart_select_preview_instance_ids_ == instance_ids &&
      smart_select_preview_candidate_instance_ids_ == candidate_instance_ids &&
      smart_select_preview_candidate_index_ == normalized_candidate_index &&
      smart_select_preview_mask_ == traced_preview_mask) {
    return;
  }
  smart_select_preview_instance_ids_ = instance_ids;
  smart_select_preview_candidate_instance_ids_ = candidate_instance_ids;
  smart_select_preview_candidate_index_ = normalized_candidate_index;
  smart_select_preview_mask_ = traced_preview_mask;
  smart_select_preview_outline_cache_valid_ = false;
  smart_select_preview_outline_cache_points_.clear();
  emit smartSelectPreviewChanged();
  if (smart_select_commit_pending_ && !smart_select_preview_mask_.isEmpty()) {
    completePendingSmartSelectCommit();
  }
}

void EditorPreviewController::updateSmartSelectPreviewResult(
    const SegmentationResult& result,
    const QVector<int>& instance_ids) {
  if (!result.success) {
    clearSmartSelectPreviewState();
    return;
  }

  const auto preview_mask =
      segmentation_mask_variant(result, QStringLiteral("object"));
  if (preview_mask.isEmpty()) {
    clearSmartSelectPreviewState();
    return;
  }

  updateSmartSelectPreviewState(preview_mask, instance_ids);
}

void EditorPreviewController::clearSmartSelectPreviewState() {
  smart_select_preview_prompts_.clear();
  updateSmartSelectPreviewState({}, {});
}

void EditorPreviewController::resetSmartSelectInstanceMap() {
  smart_select_instance_map_key_.clear();
  smart_select_instance_map_data_.clear();
  smart_select_instance_map_width_ = 0;
  smart_select_instance_map_height_ = 0;
  smart_select_instance_map_shared_cache_hit_ = false;
  resetSmartSelectPreview();
}

bool EditorPreviewController::ensureSmartSelectInstanceMap() {
  if (!vision_segmentation_available() || file_path_.isEmpty()) {
    resetSmartSelectInstanceMap();
    return false;
  }

  const auto source_key =
      generated_instance_map_cache_key(file_path_, currentState(), kSmartSelectInstanceMapPreviewEdge);
  if (source_key == smart_select_instance_map_key_ &&
      !smart_select_instance_map_data_.isEmpty() &&
      smart_select_instance_map_width_ > 0 &&
      smart_select_instance_map_height_ > 0) {
    return true;
  }

  ForegroundInstanceMap cached_instance_map;
  {
    auto& cache = foreground_instance_map_cache();
    QMutexLocker locker(&cache.mutex);
    if (cache.find(source_key, &cached_instance_map)) {
      smart_select_instance_map_key_ = source_key;
      smart_select_instance_map_data_ = cached_instance_map.instance_data;
      smart_select_instance_map_width_ = cached_instance_map.width;
      smart_select_instance_map_height_ = cached_instance_map.height;
      smart_select_instance_map_shared_cache_hit_ = true;
      return true;
    }
  }

  QImage source_image;
  if (!decodeSourceImage(&source_image, kSmartSelectInstanceMapPreviewEdge)) {
    resetSmartSelectInstanceMap();
    return false;
  }

  const auto instance_map = generate_foreground_instance_map(source_image);
  if (!instance_map.success) {
    resetSmartSelectInstanceMap();
    return false;
  }

  smart_select_instance_map_key_ = source_key;
  smart_select_instance_map_data_ = instance_map.instance_data;
  smart_select_instance_map_width_ = instance_map.width;
  smart_select_instance_map_height_ = instance_map.height;
  smart_select_instance_map_shared_cache_hit_ = false;
  {
    auto& cache = foreground_instance_map_cache();
    QMutexLocker locker(&cache.mutex);
    cache.insert(source_key, instance_map);
  }
  return true;
}

bool EditorPreviewController::loadCachedSmartSelectInstanceMap() {
  if (!vision_segmentation_available() || file_path_.isEmpty()) {
    return false;
  }

  const auto source_key =
      generated_instance_map_cache_key(file_path_, currentState(), kSmartSelectInstanceMapPreviewEdge);
  if (source_key == smart_select_instance_map_key_ &&
      !smart_select_instance_map_data_.isEmpty() &&
      smart_select_instance_map_width_ > 0 &&
      smart_select_instance_map_height_ > 0) {
    return true;
  }

  ForegroundInstanceMap cached_instance_map;
  {
    auto& cache = foreground_instance_map_cache();
    QMutexLocker locker(&cache.mutex);
    if (!cache.find(source_key, &cached_instance_map)) {
      return false;
    }
  }

  smart_select_instance_map_key_ = source_key;
  smart_select_instance_map_data_ = cached_instance_map.instance_data;
  smart_select_instance_map_width_ = cached_instance_map.width;
  smart_select_instance_map_height_ = cached_instance_map.height;
  smart_select_instance_map_shared_cache_hit_ = true;
  return true;
}

void EditorPreviewController::completePendingSmartSelectCommit() {
  if (!smart_select_commit_pending_ || smart_select_preview_mask_.isEmpty()) {
    return;
  }
  const auto customer_edit_scope = customer_edit_access_.restore();
  const auto intent = smart_select_commit_intent_;
  const auto create_new = smart_select_commit_create_new_;
  smart_select_commit_pending_ = false;
  smart_select_commit_intent_.clear();
  smart_select_commit_create_new_ = false;
  (void)acceptSmartSelectPreview(intent, create_new);
}

int EditorPreviewController::smartSelectInstanceIdAt(
    double normalized_x,
    double normalized_y) const {
  const auto instance_ids =
      smartSelectCandidateInstanceIdsAt(normalized_x, normalized_y);
  return instance_ids.isEmpty() ? 0 : instance_ids.first();
}

QVector<int> EditorPreviewController::smartSelectCandidateInstanceIdsAt(
    double normalized_x,
    double normalized_y) const {
  return smart_select_instance_candidates_from_map(
      smart_select_instance_map_data_,
      smart_select_instance_map_width_,
      smart_select_instance_map_height_,
      qBound(0.0, normalized_x, 1.0),
      qBound(0.0, normalized_y, 1.0));
}

QVector<int> EditorPreviewController::smartSelectCandidateInstanceIdsForPath(
    const QVariantList& points) const {
  return smart_select_instance_candidates_for_path(
      smart_select_instance_map_data_,
      smart_select_instance_map_width_,
      smart_select_instance_map_height_,
      normalized_smart_select_path(points));
}

QVariantMap EditorPreviewController::smartSelectPreviewMaskForInstances(
    const QVector<int>& instance_ids) const {
  return segmentation_mask_for_instances(
      smart_select_instance_map_data_,
      smart_select_instance_map_width_,
      smart_select_instance_map_height_,
      instance_ids);
}

int EditorPreviewController::findPendingRetouchMaskIndex(
    const QString& retouch_mode,
    const QString& kind) const {
  const auto normalized_retouch_mode = retouch_mode.trimmed().toLower();
  const auto normalized_kind =
      kind.trimmed().isEmpty() ? QString() : normalized_mask_kind(kind);
  for (int index = 0; index < mask_session_.stack().size(); ++index) {
    const auto mask = mask_session_.stack().at(index).toMap();
    if (mask.value(QStringLiteral("toolRole")).toString() != QStringLiteral("retouch") ||
        mask.value(QStringLiteral("committed")).toBool() ||
        mask.value(QStringLiteral("retouchMode")).toString().trimmed().toLower() !=
            normalized_retouch_mode) {
      continue;
    }
    if (!normalized_kind.isEmpty() &&
        mask.value(QStringLiteral("kind")).toString() != normalized_kind) {
      continue;
    }
    return index;
  }
  return -1;
}

int EditorPreviewController::findReusableRetouchBrushIndex(const QString& retouch_mode) const {
  const auto normalized_retouch_mode = retouch_mode.trimmed().toLower();
  if (hasActiveMask()) {
    const auto active_mask = activeMaskDefinition();
    if (active_mask.value(QStringLiteral("kind")).toString() == QStringLiteral("brush") &&
        active_mask.value(QStringLiteral("toolRole")).toString() == QStringLiteral("retouch") &&
        !active_mask.value(QStringLiteral("committed")).toBool() &&
        active_mask.value(QStringLiteral("retouchMode")).toString().trimmed().toLower() ==
            normalized_retouch_mode) {
      return mask_session_.activeIndex();
    }
  }

  return findPendingRetouchMaskIndex(normalized_retouch_mode, QStringLiteral("brush"));
}

QVariantMap EditorPreviewController::buildBrushMask(
    const QString& name,
    const QString& operation,
    const QString& tool_role,
    const QString& retouch_mode,
    bool committed,
    int ordinal) const {
  auto mask = default_mask_definition(QStringLiteral("brush"), ordinal);
  mask.insert(QStringLiteral("name"), name);
  mask.insert(QStringLiteral("operation"), normalized_mask_operation(operation));
  mask.insert(QStringLiteral("toolRole"), normalized_mask_tool_role(tool_role));
  mask.insert(QStringLiteral("retouchMode"), retouch_mode.trimmed().toLower());
  mask.insert(QStringLiteral("committed"), committed);
  if (tool_role.trimmed().toLower() != QStringLiteral("retouch")) {
    // Hand-painted coverage already includes its chosen tip and feather.
    // Generated-matte cleanup must be an explicit edit, not a hidden reshape.
    mask.insert(QStringLiteral("selectionDespeckle"), 0.0);
    mask.insert(QStringLiteral("selectionFillHoles"), 0.0);
    mask.insert(QStringLiteral("selectionRemoveIslands"), 0.0);
    mask.insert(QStringLiteral("matteCleanupProfile"), QStringLiteral("brush-painted-exact"));
  }
  return mask;
}

bool EditorPreviewController::channelMatchesSelection(const QColor& color) const {
  return channel_weight_for_selection(color.hslHueF(), hsl_channel_) > 0.0;
}

